/**
 * RSROLEPLAY Engine - Cloudflare Workers + D1
 * Auto-Installing Serverless Version
 */

// ── CONSTANTS ────────────────────────────────────────────────────────
const SECURITY_HEADERS = {
  'X-Content-Type-Options':  'nosniff',
  'X-Frame-Options':         'DENY',
  'Referrer-Policy':         'strict-origin-when-cross-origin',
  'Content-Security-Policy': "default-src 'self'; script-src 'self' 'unsafe-inline' https://cdn.tailwindcss.com https://cdn.jsdelivr.net https://cdnjs.cloudflare.com; style-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net https://fonts.googleapis.com; font-src 'self' data: https://fonts.gstatic.com https://cdn.jsdelivr.net; img-src 'self' data: blob: https:; media-src 'self' data: blob: https:; connect-src 'self' https: wss:;"
};


// ── APP ICONS ───────────────────────────────────────────
// Base64 because a single-file Worker has nowhere to keep a binary. iOS will
// not take an SVG for apple-touch-icon, which is why these exist at all.
// The maskable one keeps its mark inside the middle 62%, so a launcher that
// cuts icons to a circle does not cut the letters off with the corners.
const ICON_192 = '';
const ICON_512 = '';
const ICON_MASK_512 = '';

// Workers have atob but no Buffer, and a Response wants bytes, not a string.
function pngBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// ── INSTALLING IT ───────────────────────────────────────────────
// A manifest, and no service worker on purpose. Nothing this app serves is
// safe to hold in a cache: the page is per-account and every API answer
// carries chat history or keys, so a stale worker handing either back is a
// worse bug than not being installable. Android still offers Add to Home
// Screen from the browser menu; the automatic install banner is what a
// manifest alone does not get, because that wants a fetch handler.
//
// start_url carries no query. It is the same URL the browser would open, so an
// installed copy lands on the same session check as a tab does.
function getManifest() {
  return JSON.stringify({
    name: 'RSROLEPLAY Engine',
    short_name: 'RSROLEPLAY',
    description: 'Private AI roleplay chat.',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    orientation: 'any',
    background_color: '#0a0a0a',
    theme_color: '#0a0a0a',
    icons: [
      { src: '?action=asset&f=icon-192.png&v=' + APP_BUILD,
        sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '?action=asset&f=icon-512.png&v=' + APP_BUILD,
        sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '?action=asset&f=icon-maskable.png&v=' + APP_BUILD,
        sizes: '512x512', type: 'image/png', purpose: 'maskable' },
      { src: '?action=asset&f=icon.svg&v=' + APP_BUILD,
        sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
    ],
  });
}

// Drawn rather than shipped as a PNG, so there is no binary in a file that is
// already a megabyte of source. The safe zone for a maskable icon is the
// middle 80%, so the mark stays well inside the circle a launcher may cut.
function getAppIcon() {
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">'
       + '<rect width="512" height="512" fill="#0a0a0a"/>'
       + '<rect x="96" y="96" width="320" height="320" rx="72" fill="#2A82BA"/>'
       + '<text x="256" y="300" text-anchor="middle" fill="#ffffff"'
       + ' font-family="Segoe UI, Roboto, Helvetica, Arial, sans-serif"'
       + ' font-size="150" font-weight="700">AI</text>'
       + '</svg>';
}

// ── UTILITIES ────────────────────────────────────────────────────────
function generateId() {
  return Date.now().toString(36).padStart(11, '0') + '-' + crypto.randomUUID().replace(/-/g, '').substring(0, 8);
}

function str(val, max) {
  if (typeof val !== 'string') return null;
  const s = val.trim();
  if (s.length === 0 || s.length > max) return null;
  return s;
}

function int(val, min, max) {
  const n = Number(val);
  if (!Number.isInteger(n) || n < min || n > max) return null;
  return n;
}

function jsonResponse(data, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json', ...SECURITY_HEADERS, ...extraHeaders },
  });
}

function errResponse(msg, status = 400) {
  return jsonResponse({ error: msg }, status);
}

// ── CRYPTO ───────────────────────────────────────────────────────────
async function pbkdf2(password, saltHex = null) {
  const enc = new TextEncoder();
  let salt;
  if (saltHex) {
    salt = new Uint8Array(saltHex.match(/.{1,2}/g).map(b => parseInt(b, 16)));
  } else {
    salt = crypto.getRandomValues(new Uint8Array(16));
  }
  const keyMaterial = await crypto.subtle.importKey(
    'raw', enc.encode(password), { name: 'PBKDF2' }, false, ['deriveBits']
  );
  const hashBuffer = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt, iterations: 100_000, hash: 'SHA-256' },
    keyMaterial, 256
  );
  const toHex = arr => Array.from(arr).map(b => b.toString(16).padStart(2, '0')).join('');
  return { hash: toHex(new Uint8Array(hashBuffer)), salt: toHex(salt) };
}

async function verifyPassword(password, storedHash, storedSalt) {
  const { hash } = await pbkdf2(password, storedSalt);
  if (hash.length !== storedHash.length) return false;
  let diff = 0;
  for (let i = 0; i < hash.length; i++) diff |= hash.charCodeAt(i) ^ storedHash.charCodeAt(i);
  return diff === 0;
}


// ── TWO-FACTOR (TOTP, RFC 6238) ───────────────────────────────────────
// The scheme every authenticator app implements: a shared secret, a counter
// that advances every 30 seconds, HMAC-SHA1, and dynamic truncation down to
// six digits. WebCrypto covers all of it, so nothing is added to the bundle.

const B32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

function base32Encode(bytes) {
  let bits = 0, value = 0, out = '';
  for (const b of bytes) {
    value = (value << 8) | b; bits += 8;
    while (bits >= 5) { out += B32[(value >>> (bits - 5)) & 31]; bits -= 5; }
  }
  if (bits > 0) out += B32[(value << (5 - bits)) & 31];
  return out;
}
function base32Decode(str) {
  const s = String(str).toUpperCase().replace(/[^A-Z2-7]/g, '');
  let bits = 0, value = 0;
  const out = [];
  for (const c of s) {
    const i = B32.indexOf(c);
    if (i < 0) continue;
    value = (value << 5) | i; bits += 5;
    if (bits >= 8) { out.push((value >>> (bits - 8)) & 255); bits -= 8; }
  }
  return new Uint8Array(out);
}

async function totpAt(secretB32, step) {
  const key = await crypto.subtle.importKey(
    'raw', base32Decode(secretB32), { name: 'HMAC', hash: 'SHA-1' }, false, ['sign']
  );
  const buf = new ArrayBuffer(8);
  const view = new DataView(buf);
  view.setUint32(0, Math.floor(step / 4294967296));
  view.setUint32(4, step >>> 0);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', key, buf));
  // dynamic truncation: the low nibble of the last byte picks the offset
  const off = mac[mac.length - 1] & 0x0f;
  const bin = ((mac[off] & 0x7f) << 24) | (mac[off + 1] << 16) | (mac[off + 2] << 8) | mac[off + 3];
  return String(bin % 1000000).padStart(6, '0');
}

/* Returns the step the code belongs to, or null. A window of one step either
   side covers ordinary clock drift on a phone; anything wider starts to widen
   the guessing surface for no real benefit. */
async function totpVerify(secretB32, code, lastStep = 0) {
  const c = String(code || '').replace(/\D/g, '');
  if (c.length !== 6) return null;
  const now = Math.floor(Date.now() / 30000);
  for (let d = -1; d <= 1; d++) {
    const step = now + d;
    // a step at or before the one already accepted is a replay
    if (step <= lastStep) continue;
    const expect = await totpAt(secretB32, step);
    let diff = 0;
    for (let i = 0; i < 6; i++) diff |= expect.charCodeAt(i) ^ c.charCodeAt(i);
    if (diff === 0) return step;
  }
  return null;
}

/* Recovery codes are high-entropy, so one round of SHA-256 with the account's
   salt is enough - they do not need the work factor a password needs, and ten
   PBKDF2 rounds per login attempt would be felt. */
async function hashRecovery(code, saltHex) {
  const data = new TextEncoder().encode(saltHex + ':' + String(code).toUpperCase().replace(/[^A-Z0-9]/g, ''));
  const buf = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
}
function newRecoveryCodes(n = 10) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const raw = crypto.getRandomValues(new Uint8Array(5));
    const s = base32Encode(raw).slice(0, 8);
    out.push(s.slice(0, 4) + '-' + s.slice(4));
  }
  return out;
}

// ── D1 WRAPPER & AUTO-SETUP ──────────────────────────────────────────
class DB {
  constructor(d1) { this.d1 = d1; }

  async get(sql, params = []) {
    return (await this.d1.prepare(sql).bind(...params).first()) ?? null;
  }

  async all(sql, params = []) {
    const r = await this.d1.prepare(sql).bind(...params).all();
    return r.results ?? [];
  }

  async run(sql, params = []) {
    return this.d1.prepare(sql).bind(...params).run();
  }

  async findOne(table, where) {
    const keys = Object.keys(where);
    const sql  = `SELECT * FROM ${table} WHERE ${keys.map(k => `${k} = ?`).join(' AND ')} LIMIT 1`;
    return this.get(sql, keys.map(k => where[k]));
  }

  async insert(table, doc) {
    const keys = Object.keys(doc);
    const sql  = `INSERT INTO ${table} (${keys.join(', ')}) VALUES (${keys.map(() => '?').join(', ')})`;
    return this.run(sql, keys.map(k => doc[k]));
  }

  async update(table, where, set) {
    const setKeys   = Object.keys(set);
    const whereKeys = Object.keys(where);
    const sql = `UPDATE ${table} SET ${setKeys.map(k => `${k} = ?`).join(', ')} WHERE ${whereKeys.map(k => `${k} = ?`).join(' AND ')}`;
    return this.run(sql, [...setKeys.map(k => set[k]), ...whereKeys.map(k => where[k])]);
  }

  async delete(table, where) {
    const keys = Object.keys(where);
    const sql  = `DELETE FROM ${table} WHERE ${keys.map(k => `${k} = ?`).join(' AND ')}`;
    return this.run(sql, keys.map(k => where[k]));
  }
}

// ── ISOLATE-LOCAL READ CACHE ─────────────────────────────────────────
// A handful of rows (API keys, generation settings, personas, the shape of a
// session's context window, the logged-in session) are read on almost every
// request but only change when the user edits something. Holding them in the
// isolate turns those reads into zero D1 rows and, more importantly, takes
// whole round trips off the hot path. A write drops the entry immediately in
// the isolate that served it; another isolate keeps the old value until the
// TTL runs out, which is why the TTL is deliberately short.
const CACHE_TTL_MS = 60_000;
const _cache = new Map();

function cacheGet(key) {
  const hit = _cache.get(key);
  if (!hit) return undefined;
  if (hit.exp <= Date.now()) { _cache.delete(key); return undefined; }
  return hit.v;
}

function cacheSet(key, v, ttl = CACHE_TTL_MS) {
  // Session-keyed entries are unbounded in principle, so keep a hard ceiling.
  if (_cache.size >= 256) _cache.clear();
  _cache.set(key, { v, exp: Date.now() + ttl });
  return v;
}

function cacheDrop(prefix) {
  for (const k of [..._cache.keys()]) if (k.startsWith(prefix)) _cache.delete(k);
}

// Bumped on every deploy so browsers revalidate the HTML shell cheaply.
const APP_BUILD = '2026-09-13-geo3';
const HTML_CACHE_CONTROL = 'private, max-age=0, must-revalidate';
let _hasUsers = false, _appHTML = null, _setupHTML = null;

const SSE_HEADERS = {
  'Content-Type':    'text/event-stream; charset=utf-8',
  'Cache-Control':   'no-cache, no-transform',
  'Connection':      'keep-alive',
  'X-Accel-Buffering': 'no',   // tell any proxy in front of us not to buffer
  ...SECURITY_HEADERS,
};

// Sent when a dropped upstream stream is reconnected mid-reply.
/* Worker và Durable Object đều nhận env ngay ở cửa vào. Giữ lại một tham chiếu
   để những hàm gọi nhà cung cấp nằm sâu bên trong với tới được STREAMER, thay
   vì xâu env qua mười tầng tham số. Trong cùng một isolate env là một và chỉ
   một, không có chuyện lẫn của người này sang người kia. */
let ENV = null;

const CONTINUE_PROMPT = 'Your previous reply was cut off part-way through by a network error. Continue it from exactly where it stopped. Do not repeat any text you already wrote, do not restate, do not apologise, do not add a preamble - output only the remaining part of that reply.';

// Bump this whenever SCHEMA_SQL changes; existing databases pick the change up
// on the next cold start instead of needing a manual migration.
const SCHEMA_VERSION = '8';

// NOTE: d1.exec() requires exactly one statement per line.
const SCHEMA_SQL = [
  `CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, salt TEXT NOT NULL, created_at INTEGER);`,
  `CREATE TABLE IF NOT EXISTS user_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, session_token TEXT UNIQUE NOT NULL, csrf_token TEXT NOT NULL, expires_at INTEGER, created_at INTEGER);`,
  `CREATE TABLE IF NOT EXISTS ip_blocks (id TEXT PRIMARY KEY, failed_attempts INTEGER DEFAULT 0, locked_until INTEGER);`,
  `CREATE TABLE IF NOT EXISTS personas (id TEXT PRIMARY KEY, name TEXT NOT NULL, avatar TEXT, description TEXT, system_prompt TEXT, user_persona TEXT, greeting_message TEXT);`,
  `CREATE TABLE IF NOT EXISTS chat_sessions (id TEXT PRIMARY KEY, label TEXT, persona_id TEXT, created_at INTEGER);`,
  `CREATE TABLE IF NOT EXISTS chat_history (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, group_id TEXT NOT NULL, is_main INTEGER DEFAULT 1, role TEXT NOT NULL, content TEXT NOT NULL, timestamp INTEGER);`,
  `CREATE TABLE IF NOT EXISTS memory_state (id TEXT PRIMARY KEY, session_id TEXT UNIQUE NOT NULL, summarize_threshold INTEGER DEFAULT 50, summarize_count INTEGER DEFAULT 30, context_count INTEGER DEFAULT 20, history_fetch_count INTEGER DEFAULT 50, include_old_summary INTEGER DEFAULT 1, last_summarized_timestamp INTEGER DEFAULT 0, sketchboard_active INTEGER DEFAULT 1, current_summary TEXT);`,
  `CREATE TABLE IF NOT EXISTS sketchboard (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, content TEXT NOT NULL, is_active INTEGER DEFAULT 1, created_at INTEGER);`,
  `CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, name TEXT, provider TEXT NOT NULL, model TEXT NOT NULL, api_key TEXT, custom_url TEXT, key_mode TEXT NOT NULL, is_primary INTEGER DEFAULT 0, created_at INTEGER);`,
  `CREATE TABLE IF NOT EXISTS gen_settings (id TEXT PRIMARY KEY, preset TEXT, temperature REAL, top_p REAL, presence_penalty REAL, frequency_penalty REAL, top_k INTEGER, repetition_penalty REAL, max_tokens INTEGER, updated_at INTEGER);`,
  `CREATE TABLE IF NOT EXISTS user_prefs (user_id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER);`,
  `CREATE TABLE IF NOT EXISTS _schema_meta (k TEXT PRIMARY KEY, v TEXT);`,
  // Indexes. Without these every history read is a full scan of chat_history,
  // which is what made loading a long session feel slow.
  `CREATE INDEX IF NOT EXISTS idx_ch_sess_main_ts ON chat_history (session_id, is_main, timestamp);`,
  `CREATE INDEX IF NOT EXISTS idx_ch_sess_ts ON chat_history (session_id, timestamp);`,
  `CREATE INDEX IF NOT EXISTS idx_ch_group_ts ON chat_history (group_id, timestamp);`,
  `CREATE INDEX IF NOT EXISTS idx_sb_sess_active ON sketchboard (session_id, is_active, created_at);`,
  `CREATE INDEX IF NOT EXISTS idx_us_user ON user_sessions (user_id);`,
  `CREATE INDEX IF NOT EXISTS idx_us_expires ON user_sessions (expires_at);`,
  `CREATE INDEX IF NOT EXISTS idx_cs_created ON chat_sessions (created_at);`,
  // In-flight reply tracking, so a client can follow a generation that outlived
  // its connection (see generationStatus).
  `CREATE TABLE IF NOT EXISTS active_generations (bot_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, group_id TEXT NOT NULL, state TEXT NOT NULL, error TEXT, updated_at INTEGER);`,
  `CREATE INDEX IF NOT EXISTS idx_ag_session ON active_generations (session_id);`,
  `CREATE INDEX IF NOT EXISTS idx_ak_mode ON api_keys (key_mode, is_primary);`,
].join('\n');

// The schema probe used to run on EVERY request, costing one extra D1 round
// trip each time. It is memoised per isolate now: one query per cold start.
let _schemaReady = null;

/* Column additions, applied after the CREATE TABLE batch. They are separate
   because d1.exec() runs its statements as one unit: an ALTER that fails
   because the column is already there would take the whole batch down with
   it. Each is attempted on its own and its failure is the expected outcome on
   a database that has already been migrated. */
const MIGRATIONS = [
  `ALTER TABLE users ADD COLUMN totp_secret TEXT`,
  `ALTER TABLE users ADD COLUMN totp_enabled INTEGER DEFAULT 0`,
  `ALTER TABLE users ADD COLUMN totp_last_step INTEGER DEFAULT 0`,
  `ALTER TABLE users ADD COLUMN recovery_codes TEXT`,
  `ALTER TABLE users ADD COLUMN mfa_fails INTEGER DEFAULT 0`,
  `ALTER TABLE users ADD COLUMN mfa_stage INTEGER DEFAULT 0`,
  `ALTER TABLE users ADD COLUMN mfa_locked_until INTEGER DEFAULT 0`,
  `CREATE TABLE IF NOT EXISTS user_prefs (user_id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER)`,
];

function ensureSchema(db) {
  if (!_schemaReady) {
    _schemaReady = (async () => {
      try {
        const row = await db.get('SELECT v FROM _schema_meta WHERE k = ?', ['version']);
        if (row?.v === SCHEMA_VERSION) return;
      } catch { /* table missing: fresh install, or a database from before versioning */ }
      await db.d1.exec(SCHEMA_SQL);
      for (const stmt of MIGRATIONS) {
        try { await db.run(stmt); } catch { /* already applied */ }
      }
      await db.run('INSERT OR REPLACE INTO _schema_meta (k, v) VALUES (?, ?)', ['version', SCHEMA_VERSION]);
    })().catch(e => { _schemaReady = null; throw e; });
  }
  return _schemaReady;
}

// ── AUTH HELPERS ─────────────────────────────────────────────────────
function getIP(req) {
  return req.headers.get('cf-connecting-ip') ?? '0.0.0.0';
}

async function checkBlock(req, db) {
  const block = await db.findOne('ip_blocks', { id: getIP(req) });
  if (block?.locked_until && Date.now() < block.locked_until) {
    const diff = Math.ceil((block.locked_until - Date.now()) / 1000);
    return `IP locked. Try in ${Math.floor(diff / 60)}m ${diff % 60}s.`;
  }
  return null;
}

/* Tries allowed in each round, and the wait that follows a round that runs
   out. Three tries only the first time - after that a single wrong code costs
   the next wait, and the fourth costs the account. Six wrong codes in all. */
/* The only thing a wrong code is ever answered with. */
const MFA_RETRY = 'Please try again.';
const MFA_TRIES = [3, 1, 1, 1];
const MFA_LOCK_STEPS = [10 * 60 * 1000, 30 * 60 * 1000, 60 * 60 * 1000];

/* Counts one wrong code and returns what should happen next.
   Reached only after the password has already verified. */
async function mfaFail(db, user) {
  const stage = user.mfa_stage || 0;                  // rounds already spent
  const allowed = MFA_TRIES[Math.min(stage, MFA_TRIES.length - 1)];
  const fails = (user.mfa_fails || 0) + 1;

  if (fails < allowed) {
    await db.update('users', { id: user.id }, { mfa_fails: fails });
    return { left: allowed - fails };
  }

  const next = stage + 1;
  if (next > MFA_LOCK_STEPS.length) {
    /* No wait left to impose. The account is made unusable rather than
       deleted: an empty users table is what reopens first-time setup, so
       deleting the row handed the whole instance - every chat, every key - to
       whoever made the last wrong guess. Its name and password become random
       noise instead. Nobody can sign in to it again, and because the row is
       still there, setup stays closed. */
    const noise = () => Array.from(crypto.getRandomValues(new Uint8Array(24)),
                                   b => b.toString(16).padStart(2, '0')).join('');
    await db.run('DELETE FROM user_sessions WHERE user_id = ?', [user.id]);
    await db.run('UPDATE users SET username = ?, password_hash = ?, salt = ?, mfa_fails = 0, mfa_stage = 0, mfa_locked_until = 0 WHERE id = ?',
                 [noise(), noise(), noise(), user.id]);
    return { deleted: true };
  }
  const until = Date.now() + MFA_LOCK_STEPS[next - 1];
  await db.update('users', { id: user.id }, { mfa_fails: 0, mfa_stage: next, mfa_locked_until: until });
  return { lockedUntil: until, stage: next, nextTries: MFA_TRIES[Math.min(next, MFA_TRIES.length - 1)] };
}
async function mfaPass(db, user, extra = {}) {
  await db.update('users', { id: user.id },
    Object.assign({ mfa_fails: 0, mfa_stage: 0, mfa_locked_until: 0 }, extra));
}

async function failLogin(req, db) {
  const ip    = getIP(req);
  const block = await db.findOne('ip_blocks', { id: ip });
  const attempts = (block?.failed_attempts ?? 0) + 1;
  const locked_until = attempts >= 3 ? Date.now() + 30 * 60 * 1000 : null;
  if (block) {
    await db.update('ip_blocks', { id: ip }, { failed_attempts: attempts, locked_until });
  } else {
    await db.insert('ip_blocks', { id: ip, failed_attempts: attempts, locked_until });
  }
}

async function clearBlock(req, db) {
  await db.delete('ip_blocks', { id: getIP(req) });
}

// The session row is looked up on every single API call. Caching it briefly
// takes that round trip off the front of every request. Logout, a credential
// change and the nuke button all clear it in the isolate that served them, and
// the short TTL bounds how long any other isolate can lag behind.
const AUTH_TTL_MS = 30_000;

async function auth(req, db) {
  const cookie = req.headers.get('Cookie') ?? '';
  const match  = cookie.match(/(?:^|;\s*)rsroleplay_sess=([A-Za-z0-9\-]+)/);
  if (!match) return null;
  const token = match[1];
  if (!/^[0-9a-f-]{36}$/i.test(token)) return null;

  const cached = cacheGet('auth:' + token);
  if (cached) return cached.expires_at < Date.now() ? null : cached;

  const session = await db.findOne('user_sessions', { session_token: token });
  if (!session) return null;
  if (session.expires_at < Date.now()) {
    await db.delete('user_sessions', { session_token: token });
    return null;
  }
  return cacheSet('auth:' + token, session, AUTH_TTL_MS);
}

// ── MEMORY & CONTEXT ─────────────────────────────────────────────────
const MEM_DEFAULTS = {
  summarize_threshold: 50, summarize_count: 30, context_count: 20,
  history_fetch_count: 50, include_old_summary: 1, sketchboard_active: 1,
};

function newMemRow(sid, global) {
  return {
    id: generateId(),
    session_id:                sid,
    summarize_threshold:       global?.summarize_threshold ?? MEM_DEFAULTS.summarize_threshold,
    summarize_count:           global?.summarize_count     ?? MEM_DEFAULTS.summarize_count,
    context_count:             global?.context_count       ?? MEM_DEFAULTS.context_count,
    history_fetch_count:       global?.history_fetch_count ?? MEM_DEFAULTS.history_fetch_count,
    include_old_summary:       global?.include_old_summary ?? MEM_DEFAULTS.include_old_summary,
    last_summarized_timestamp: 0,
    sketchboard_active:        global?.sketchboard_active  ?? MEM_DEFAULTS.sketchboard_active,
    current_summary:           null,
  };
}

// Writing the defaulted row is not something the caller needs to wait for, so
// hand it to waitUntil when we have an execution context. INSERT OR IGNORE
// keeps two concurrent requests from colliding on session_id's UNIQUE index.
function persistMemRow(db, row, ctx) {
  const keys = Object.keys(row);
  const p = db.run(
    `INSERT OR IGNORE INTO memory_state (${keys.join(', ')}) VALUES (${keys.map(() => '?').join(', ')})`,
    keys.map(k => row[k])
  ).catch(() => {});
  if (ctx?.waitUntil) { ctx.waitUntil(p); return; }
  return p;
}

// The session's own row and the global defaults, in one statement rather than
// two. Callers pick the one they want out of the result with pickMem.
const MEM_PAIR_SQL = "SELECT * FROM memory_state WHERE session_id IN (?, 'global')";

function pickMem(rows, sid) {
  return (rows ?? []).find(r => r.session_id === sid) ?? null;
}

function clampCtx(n) {
  return Math.max(1, Math.min(n ?? 20, 100));
}

function clampFetch(n) {
  return Math.max(10, Math.min(n ?? 50, 200));
}

// Keeps a cached context shape in step with a memory row we just read for real,
// without inventing a persona id we have not seen.
function rememberShape(sid, mem) {
  const prev = cacheGet('shape:' + sid);
  if (prev) {
    cacheSet('shape:' + sid, {
      ...prev,
      ctxCount:   clampCtx(mem.context_count),
      fetchCount: clampFetch(mem.history_fetch_count),
      wantPins:   mem.sketchboard_active === 1,
    });
  }
  return mem;
}

// One statement, one round trip.
async function getMem(sid, db, ctx = null) {
  const rows = await db.all(MEM_PAIR_SQL, [sid]);
  const row  = pickMem(rows, sid);
  if (row) return rememberShape(sid, row);
  const fresh = newMemRow(sid, pickMem(rows, 'global'));
  await persistMemRow(db, fresh, ctx);
  return fresh;
}

function pinStmt(db, sid) {
  return db.d1.prepare('SELECT content FROM sketchboard WHERE session_id = ? AND is_active = 1 ORDER BY created_at DESC').bind(sid);
}

function histStmt(db, sid, beforeTs, ctxCount) {
  return beforeTs
    // Exact immediate history prior to the regenerated message, ignoring summary markers.
    ? db.d1.prepare('SELECT role, content FROM chat_history WHERE session_id = ? AND is_main = 1 AND timestamp < ? ORDER BY timestamp DESC LIMIT ?').bind(sid, beforeTs, ctxCount)
    : db.d1.prepare('SELECT role, content FROM chat_history WHERE session_id = ? AND is_main = 1 ORDER BY timestamp DESC LIMIT ?').bind(sid, ctxCount);
}

// Returns { msgs, mem, bot } — mem comes back so callers don't have to re-query it.
// What the context query looks like (which persona, how many messages, whether
// pins are on) depends on rows that only change when the user edits settings,
// so once that shape is cached the whole context loads in a single round trip.
// A cold isolate still takes two, and the memory row itself is always read
// fresh so a newly written summary is never missed.
async function buildCtx(sid, userMsg, db, beforeTs = null, ctx = null) {
  let shape    = cacheGet('shape:' + sid);
  let personas = cacheGet('personas');

  const stmts = [];
  const at    = {};
  at.mem = stmts.push(db.d1.prepare(MEM_PAIR_SQL).bind(sid)) - 1;
  if (!shape)    at.sess     = stmts.push(db.d1.prepare('SELECT persona_id FROM chat_sessions WHERE id = ? LIMIT 1').bind(sid)) - 1;
  if (!personas) at.personas = stmts.push(db.d1.prepare('SELECT * FROM personas ORDER BY id')) - 1;
  if (shape) {
    if (shape.wantPins) at.pins = stmts.push(pinStmt(db, sid)) - 1;
    at.hist = stmts.push(histStmt(db, sid, beforeTs, shape.ctxCount)) - 1;
  }
  const res = await db.d1.batch(stmts);

  if (!personas) personas = cacheSet('personas', res[at.personas].results ?? []);

  const memRows = res[at.mem].results;
  let mem = pickMem(memRows, sid);
  if (!mem) {
    mem = newMemRow(sid, pickMem(memRows, 'global'));
    await persistMemRow(db, mem, ctx);
  }

  let pins, history;
  if (shape) {
    pins    = shape.wantPins ? (res[at.pins].results ?? []) : [];
    history = res[at.hist].results ?? [];
  } else {
    shape = cacheSet('shape:' + sid, {
      personaId:  res[at.sess].results?.[0]?.persona_id ?? null,
      ctxCount:   clampCtx(mem.context_count),
      fetchCount: clampFetch(mem.history_fetch_count),
      wantPins:   mem.sketchboard_active === 1,
    });
    const stmts2 = [];
    if (shape.wantPins) stmts2.push(pinStmt(db, sid));
    stmts2.push(histStmt(db, sid, beforeTs, shape.ctxCount));
    const res2 = await db.d1.batch(stmts2);
    pins    = shape.wantPins ? (res2[0].results ?? []) : [];
    history = res2[shape.wantPins ? 1 : 0].results ?? [];
  }

  // No persona set, or one that has since been deleted, falls back to the first
  // persona — exactly what the old LEFT JOIN did.
  const bot = personas.find(p => p.id === shape.personaId) ?? personas[0] ?? null;

  const sysParts = [];
  if (bot?.system_prompt) sysParts.push(bot.system_prompt);
  if (bot?.user_persona)  sysParts.push('About the user: ' + bot.user_persona);
  if (pins.length > 0) {
    sysParts.push('Additional important infomation. Use this important infomation to continue the story:\n- ' + pins.map(p => p.content).join('\n- '));
  }

  const msgs = [];
  if (sysParts.length > 0) msgs.push({ role: 'system', content: sysParts.join('\n\n') });
  if (mem.current_summary) msgs.push({ role: 'system', content: 'Previous summary:\n' + mem.current_summary });

  history.reverse();
  for (const h of history) {
    // Strip <think> blocks so they don't consume context tokens. The regex only
    // runs when there is one to strip.
    const cleanContent = (h.content.indexOf('<think>') === -1 ? h.content
                          : h.content.replace(/<think>[\s\S]*?<\/think>/gi, '')).trim();
    // A failed generation leaves an empty bot row behind so the user's message
    // survives (see reserveTurn). It must never reach a provider: an
    // empty assistant turn is a 400 on Gemini and confuses everything else.
    if (!cleanContent) continue;
    msgs.push({ role: h.role === 'bot' ? 'assistant' : 'user', content: cleanContent });
  }
  if (userMsg) msgs.push({ role: 'user', content: userMsg });
  return { msgs, mem, bot };
}

// ── LLM ──────────────────────────────────────────────────────────────
const THINKING_EFFORTS = new Set(['none', 'low', 'medium', 'high']);

// -- GENERATION SETTINGS ----------------------------------------------
// One global row drives every API endpoint, so switching provider does not
// change how the model behaves. 'default' is the tuning this app shipped with.
const GEN_PRESETS = {
  default:  { temperature: 0.3, top_p: 0.8,  presence_penalty: 0.1, frequency_penalty: 0.1, max_tokens: 8192 },
  creative: { temperature: 1.0, top_p: 0.95, presence_penalty: 0.4, frequency_penalty: 0.4, max_tokens: 8192 },
  precise:  { temperature: 0.1, top_p: 0.5,  presence_penalty: 0.0, frequency_penalty: 0.0, max_tokens: 8192 },
};
const GEN_PRESET_NAMES = ['default', 'creative', 'precise', 'custom'];

// field: [min, max, fallback]
const GEN_LIMITS = {
  temperature:        [0,   2,     0.3],
  top_p:              [0,   1,     0.8],
  presence_penalty:   [-2,  2,     0.1],
  frequency_penalty:  [-2,  2,     0.1],
  top_k:              [0,   200,   0],     // 0 = do not send
  repetition_penalty: [0,   2,     0],     // 0 = do not send
  max_tokens:         [256, 32768, 8192],
};

function clampNum(v, lo, hi, dflt) {
  const n = Number(v);
  if (!Number.isFinite(n)) return dflt;
  return Math.min(hi, Math.max(lo, n));
}

// The stored numbers, clamped. These are what the Custom preset uses.
function rawGen(row) {
  const out = {};
  for (const [k, [lo, hi, d]] of Object.entries(GEN_LIMITS)) out[k] = clampNum(row?.[k], lo, hi, d);
  out.max_tokens = Math.round(out.max_tokens);
  out.top_k      = Math.round(out.top_k);
  return out;
}

// What actually gets sent to a provider.
function resolveGen(row) {
  const preset = GEN_PRESET_NAMES.includes(row?.preset) ? row.preset : 'default';
  if (preset === 'custom') return { preset, ...rawGen(row) };
  return { preset, ...GEN_PRESETS[preset], top_k: 0, repetition_penalty: 0 };
}

// API keys and the global generation settings. Both only change from the
// settings modals, so after the first read they come out of the isolate cache
// for free - this used to be a full scan of api_keys on every single message.
async function loadKeysAndGen(db) {
  const hit = cacheGet('cfg');
  if (hit) return hit;
  const [keysRes, genRes] = await db.d1.batch([
    db.d1.prepare('SELECT * FROM api_keys'),
    db.d1.prepare('SELECT * FROM gen_settings WHERE id = ? LIMIT 1').bind('global'),
  ]);
  return cacheSet('cfg', { apiKeys: keysRes.results ?? [], gen: resolveGen(genRes.results?.[0]) });
}

// How long we wait for an upstream provider to send response HEADERS. Once the
// body starts streaming the abort is cleared and the stream layer's own stall
// watchdog takes over, so a slow generation is never cut short.
/* Chờ header của nhà cung cấp. Gemini với ngữ cảnh dài hoặc model biết suy
   luận thường mất 30-50 giây mới gửi byte đầu, nên mốc 30 giây cũ cắt ngang
   những câu trả lời hoàn toàn bình thường. Vẫn để dưới STREAM_FIRST_BYTE_MS
   (90s) để tầng stream mới là chỗ quyết định cuối cùng. */
const LLM_HEADER_TIMEOUT_MS = 60_000;
const LLM_TOTAL_TIMEOUT_MS  = 120_000; // non-streaming calls (summarize)

/* Thử lại những lỗi đáng thử lại: hết giờ khi chưa nhận được byte nào, 429,
   hoặc 5xx. Lỗi 4xx thì không - request sai thì gửi lại vẫn sai y hệt.

   Ba lần, nghỉ 1.2 giây rồi 3 giây. Con số lấy từ đo đạc chứ không phải đoán:
   một model gemini đang bận trả "high demand" chỉ sau khoảng hai giây, và
   thường rảnh lại trong vài giây kế tiếp. Một lần thử lại là không đủ.

   Ở đây chưa có chữ nào được stream về máy người dùng nên gửi lại là an toàn,
   không thể nhân đôi nội dung. Thân của lần hỏng phải được huỷ, nếu không kết
   nối đó vẫn bị giữ và tính vào giới hạn sáu kết nối đồng thời của Worker. */
const LLM_RETRY_WAITS = [1200, 3000];

/* Một lỗi 429 có hai loại rất khác nhau, và Google nói rõ loại nào trong thân
   lỗi. Hết lượt trong PHÚT thì chờ vài giây là qua. Hết lượt trong NGÀY thì
   thử lại không bao giờ thành công - mà lại tốn thêm lượt, trong khi gói miễn
   phí chỉ cho hai mươi lượt một ngày trên vài model. Đo trực tiếp trên API:
   quotaId "GenerateRequestsPerDayPerProjectPerModel-FreeTier", quotaValue 20. */
function hetLuotCaNgay(text) {
  return /PerDay|per day|daily limit|quota.{0,40}today/i.test(text || '');
}

async function fetchLLM(url, init, ms, signal) {
  for (let lan = 0; ; lan++) {
    const nghi = LLM_RETRY_WAITS[lan];
    try {
      const res = await fetchWithTimeout(url, init, ms, signal);
      /* Bị chặn vì vị trí thì hỏi lại từ vùng khác, ngay trên đường mà mọi tin
         nhắn đi qua. Chỉ lỗi này mới đi vòng: nhà cung cấp khác không bao giờ
         trả lỗi này nên không ai phải chịu thêm chặng đường vô ích. Chưa có
         chữ nào chảy về máy người dùng nên gửi lại là an toàn. */
      if (!res.ok && (res.status === 400 || res.status === 403)) {
        const raw = await readBodyWithTimeout(res, ERROR_BODY_TIMEOUT_MS).catch(() => '');
        const vong = await thuLaiTuVungKhac(null, url, init, ms, raw);
        return vong || new Response(raw, { status: res.status });
      }
      if (nghi !== undefined && (res.status === 429 || res.status >= 500)) {
        if (res.status === 429) {
          // Thân lỗi phải đọc mới biết nên chờ hay nên bỏ cuộc; đọc xong thì
          // dựng lại Response để chỗ gọi vẫn lấy được nguyên văn của Google.
          let text = '';
          try { text = await readBodyWithTimeout(res, ERROR_BODY_TIMEOUT_MS); } catch {}
          if (hetLuotCaNgay(text)) return new Response(text, { status: 429 });
          await new Promise(r => setTimeout(r, nghi));
          continue;
        }
        try { await res.body?.cancel(); } catch {}
        await new Promise(r => setTimeout(r, nghi));
        continue;
      }
      return res;
    } catch (e) {
      if (nghi === undefined || (signal && signal.aborted)) throw e;
      await new Promise(r => setTimeout(r, nghi));
    }
  }
}

async function fetchWithTimeout(url, init, ms, extSignal) {
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(new Error('Upstream timed out after ' + ms + 'ms')), ms);
  const onAbort = () => ac.abort(extSignal.reason);
  if (extSignal) {
    if (extSignal.aborted) ac.abort(extSignal.reason);
    else extSignal.addEventListener('abort', onAbort, { once: true });
  }
  try {
    return await fetch(url, { ...init, signal: ac.signal });
  } finally {
    clearTimeout(timer);
    if (extSignal) extSignal.removeEventListener('abort', onAbort);
  }
}

// fetch() settles as soon as the response HEADERS arrive, so the timeout above
// stops covering anything the moment the body starts. A provider that stalls
// half-way through its body would hang this read forever, and an abandoned body
// keeps its connection open - which counts against the Worker's six
// simultaneous connections and makes every later fetch() queue behind it. That
// is how one bad upstream turned into "nothing works any more". Reading a body
// therefore gets its own deadline and always hands the connection back.
async function readBodyWithTimeout(res, ms) {
  let timer;
  try {
    return await Promise.race([
      res.text(),
      new Promise((_, rej) => { timer = setTimeout(() => rej(new Error('Upstream body timed out after ' + ms + 'ms')), ms); }),
    ]);
  } catch (e) {
    try { await res.body?.cancel(); } catch { /* already gone */ }
    throw e;
  } finally {
    clearTimeout(timer);
  }
}

// An error body only feeds the message we display, so it gets a short leash of
// its own: a provider that never finishes sending its 500 page must not be able
// to stall the failover to the next key.
const ERROR_BODY_TIMEOUT_MS = 10_000;

/* Google từ chối Gemini API theo vị trí máy gửi request; Hong Kong nằm ngoài
   danh sách được phép. Worker chạy tại colo mà trình duyệt vào, mà Cloudflare
   đưa khách Việt Nam qua Hong Kong khoảng một nửa số lần - nên cùng một khoá
   lúc dùng được lúc không, không theo quy luật nào nhìn thấy được. */
function laLoiViTri(text) {
  return /User location is not supported|FAILED_PRECONDITION/i.test(text || '');
}

/* Durable Object nằm ở nơi mình chọn được, khác với Worker. Ghim nó ở Bắc Mỹ:
   vùng này luôn nằm trong danh sách Google cho phép, và mấy lệnh gọi đi qua đây
   đều là loại bấm một lần (thử khoá, lấy danh sách model) nên thêm vài trăm
   mili giây không ai thấy. Tin nhắn thật vẫn đi bằng Durable Object của phiên
   chat, không đổi vị trí, không chậm thêm. */
const PROBE_LOCATION = 'enam';

async function fetchQuaStreamer(env, url, init, ms) {
  const e = env || ENV;
  if (!e || !e.STREAMER) return null;      // máy chủ chưa cài Durable Object
  const stub = e.STREAMER.get(e.STREAMER.idFromName('probe'), { locationHint: PROBE_LOCATION });
  const res = await stub.fetch('https://streamer/probe', {
    method: 'POST',
    body: JSON.stringify({ url, init, ms }),
  });
  if (res.status === 599) throw new Error(await res.text());
  return res;
}

/* Một lệnh gọi vừa bị từ chối vì vị trí thì hỏi lại từ Durable Object đã ghim
   vùng. Trả về null khi không đi vòng được, để chỗ gọi giữ nguyên lỗi gốc. */
async function thuLaiTuVungKhac(env, url, init, ms, raw) {
  if (!laLoiViTri(raw)) return null;
  try { return await fetchQuaStreamer(env, url, init, ms); }
  catch { return null; }                   // đường vòng cũng hỏng: giữ lỗi gốc
}

/* Gọi nhà cung cấp. Luôn trả về Response để chỗ gọi không phải biết đã đi
   đường nào. Dùng cho nút Thử và danh sách model; tin nhắn thật đi qua
   fetchLLM, chỗ đó có cùng đường vòng này. */
async function providerCall(env, url, init, ms) {
  const res = await fetchWithTimeout(url, init, ms, null);
  if (res.ok) return res;
  const body = await readBodyWithTimeout(res, ERROR_BODY_TIMEOUT_MS).catch(() => '');
  return (await thuLaiTuVungKhac(env, url, init, ms, body)) || new Response(body, { status: res.status });
}

function isThinking(model) {
  const m = model.toLowerCase();
  return ['gemma-4', 'qwen3', 'deepseek-r1', 'gpt-oss', ':thinking', '-think'].some(x => m.includes(x));
}

// ── WHERE A KEY'S CHAT REQUESTS GO ────────────────────────────────
// One answer for the chat path and the Test button. The Test button used to
// carry its own copy of this list; the copy had no branch for imgxh, so testing
// an imgxh key fetched a null URL - and it skipped the custom-URL checks below.
function chatTarget(key) {
  const p = key.provider;
  if (p === 'cloudflare') return { url: `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(key.custom_url)}/ai/v1/chat/completions`, headers: {} };
  if (p === 'groq')       return { url: 'https://api.groq.com/openai/v1/chat/completions', headers: {} };
  if (p === 'mistral')    return { url: 'https://api.mistral.ai/v1/chat/completions', headers: {} };
  if (p === 'gemini')     return { url: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions', headers: {} };
  if (p === 'imgxh')      return { url: 'https://imgxh.eu.org/v1/chat/completions', headers: {} };
  if (p === 'openrouter') return { url: 'https://openrouter.ai/api/v1/chat/completions', headers: { 'X-Title': 'RSROLEPLAY Engine' } };
  if (p === 'custom') {
    if (!key.custom_url) throw new Error('Custom provider requires a URL');
    try {
      const u = new URL(key.custom_url);
      if (u.protocol !== 'https:') throw new Error('Custom URLs must use HTTPS');
      // Block internal and reserved IP addresses
      const h = u.hostname;
      if (h === 'localhost' || h === '127.0.0.1' || h.startsWith('10.') ||
          h.startsWith('192.168.') || h.startsWith('169.254.')) {
        throw new Error('Local or Internal network requests are strictly forbidden.');
      }
    } catch (e) {
      throw new Error('Invalid custom URL: ' + e.message);
    }
    return { url: key.custom_url, headers: {} };
  }
  throw new Error('Unknown provider: ' + p);
}

async function executeLLM(apiKeys, messages, mode, thinkingEffort, stream, signal, gen = null) {
  const effort = THINKING_EFFORTS.has(thinkingEffort) ? thinkingEffort : 'none';
  const g = gen ?? resolveGen(null);
let keys = apiKeys.filter(k => k.key_mode === mode).sort((a, b) => b.is_primary - a.is_primary);
  if (keys.length === 0) throw new Error('No API keys configured for mode: ' + mode);

  /* Trước đây chỗ này khoá lại: khoá chính là Gemini thì CHỈ thử Gemini, để lỗi
     của Gemini hiện ra thay vì lặng lẽ chuyển sang nhà cung cấp khác. Nó có ích
     hồi đi tìm lỗi, nhưng nó cắt mất đường lùi - hết lượt trong ngày, model quá
     tải, hay bị chặn vì vùng thì đoạn chat chết hẳn, dù trong máy còn khoá khác
     dùng được. Lỗi Gemini bây giờ đã được gọi đúng tên nên không cần khoá nữa,
     và khi mọi khoá đều hỏng thì lỗi vẫn hiện ra đầy đủ. */

  let lastErr = '';
  let geminiError = null;
  for (const key of keys) {
    try {
      const { provider } = key;
      // A server calling an API should look like one. The browser impersonation
      // this used to send (a fake Chrome UA, Sec-Fetch-* headers, and a random
      // X-Forwarded-For on every request) is a textbook bot signature and a
      // plausible way to get a whole Cloudflare egress IP throttled - which
      // would explain "works from any other client, dead from this one until
      // the VPN moves me to another colo".
      const headers = {
        'Content-Type':  'application/json',
        'Accept':        stream ? 'text/event-stream' : 'application/json',
        'Authorization': `Bearer ${key.api_key ?? ''}`,
        'User-Agent':    'rsroleplay-worker/1.0',
      };
      
      // ── 1. URL LOGIC ── (shared with the Test button, see chatTarget)
      const target = chatTarget(key);
      let url = target.url;
      Object.assign(headers, target.headers);

      // ── 2. MODEL ID LOGIC ──
      const modelId = (provider === 'cloudflare' && !key.model.startsWith('@cf/')) 
                      ? `@cf/${key.model}` 
                      : key.model;

      const body = { model: modelId, messages, stream };

      // ── 3. PARAMETERS LOGIC ──
if (mode === 'chat') {
        // Driven by the global Advanced Settings row (see resolveGen).
        body.max_tokens  = g.max_tokens;
        body.temperature = g.temperature;
        body.top_p       = g.top_p;
        // Gemini's OpenAI-compat endpoint rejects penalty params on many models — skip them
        if (provider !== 'gemini') {
          body.presence_penalty  = g.presence_penalty;
          body.frequency_penalty = g.frequency_penalty;
        }
        // Not part of the OpenAI schema. Only sent when explicitly turned on,
        // and only to providers that tolerate extra fields - a stray parameter
        // is a 400 on Groq/Gemini, which is exactly the kind of failure that
        // used to look like a dropped connection.
        if (provider === 'openrouter' || provider === 'custom') {
          if (g.top_k > 0)              body.top_k = g.top_k;
          if (g.repetition_penalty > 0) body.repetition_penalty = g.repetition_penalty;
        }

        // PHP FIX: ONLY inject thinking logic if we are in CHAT mode
if (isThinking(key.model) && provider !== 'gemini') {
          if (provider === 'groq') {
            // Groq R1 models FORBID temperature, top_p, and penalties. 
            // We must remove them to avoid API rejection.
            delete body.temperature;
            delete body.top_p;
            delete body.presence_penalty; // <--- Added
            delete body.frequency_penalty; // <--- Added
            // Explicitly set reasoning_effort to "none" if effort is off
            body.reasoning_effort = (effort === 'none') ? 'none' : effort;
          } else if (provider === 'openrouter') {
            body.include_reasoning = true;
            if (effort !== 'none') body.reasoning = { effort };
          } else if (provider === 'custom' && key.custom_url.includes('nvidia.com')) {
  body.chat_template_kwargs = { 
    "enable_thinking": true 
  };
}
        }
      } else {
        // Summarize mode: Keep it very standard (Matching your PHP line 301)
        body.max_tokens = 2048;
        body.temperature = 0.8;
        // NEVER send reasoning_effort or penalties during summarization for Groq
      }

const res = await fetchLLM(
        url,
        { method: 'POST', headers, body: JSON.stringify(body) },
        stream ? LLM_HEADER_TIMEOUT_MS : LLM_TOTAL_TIMEOUT_MS,
        signal
      );
      if (!res.ok) { 
        let errorBody = '';
        try { errorBody = await readBodyWithTimeout(res, ERROR_BODY_TIMEOUT_MS); }
        catch (be) { errorBody = '(error body unreadable: ' + be.message + ')'; }
        lastErr = `${provider} HTTP ${res.status}: ${errorBody.substring(0, 150)}`;
        /* 503 và 429 là hai lỗi hay gặp nhất, và cũng là hai lỗi người dùng tự
           xử lý được - nhưng chỉ khi hiểu nó nói gì, mà nguyên khối JSON tiếng
           Anh của Google thì không. Dòng đầu để nguyên văn cố định cho srvErr
           dịch được; tên model xuống dòng dưới. */
        if (laLoiViTri(errorBody)) lastErr = 'This provider does not serve the region this server is running in';
        const busy = res.status === 503
          ? 'This model is busy right now. Wait a moment, or pick another model.'
          : res.status !== 429
          ? null
          : hetLuotCaNgay(errorBody)
          ? 'This model has used up its free allowance for today. Pick another model, or come back tomorrow.'
          : 'This model is over its rate limit. Wait a minute, or pick another model.';
        if (busy) {
          /* Google kèm luôn số lượt được phép. Nói ra thì người dùng biết ngay
             model đang dùng rẻ hay đắt, thay vì đoán. */
          const soLuot = /"quotaValue":\s*"?(\d+)/.exec(errorBody);
          lastErr = `${busy}\n\nModel: ${modelId}` + (soLuot ? ` (${soLuot[1]}/day)` : '');
        }
        // GEMINI DEBUG: keep the full, untruncated Google error so we can show it in chat
        if (provider === 'gemini') {
          geminiError = busy
            ? `${busy}\n\nModel: ${key.model}`
            : `Gemini HTTP ${res.status}\n\nModel: ${key.model}\nEndpoint: ${url}\n\nGoogle response:\n${errorBody.substring(0, 1500)}`;
        }
        continue; 
      }

      if (stream) return { provider, stream: res.body };

      const rawBody = await readBodyWithTimeout(res, LLM_TOTAL_TIMEOUT_MS);
      let data;
      try { data = JSON.parse(rawBody); }
      catch { throw new Error('Upstream returned a non-JSON body: ' + rawBody.substring(0, 150)); }
      const msg = data.choices?.[0]?.message;
      if (!msg) throw new Error('No message returned from API');
      
let content = msg.content ?? '';
      const reasoning = msg.reasoning ?? '';
      // Some Gemma/Gemini models emit reasoning as <thought>…</thought>. Normalize to <think>.
      content = content.replace(/<thought>/gi, '<think>').replace(/<\/thought>/gi, '</think>');
      return reasoning ? `<think>\n${reasoning}\n</think>\n\n${content}` : content;

} catch (e) {
      lastErr = e.message;
      if (key.provider === 'gemini') {
        geminiError = `Gemini request failed\n\nModel: ${key.model}\n\nError: ${e.message}`;
      }
    }
  }
// If a Gemini key was the thing that failed, throw a tagged error carrying Google's real message
  if (geminiError) {
    const err = new Error(geminiError);
    err.isGeminiDebug = true;
    throw err;
  }
  throw new Error('All API keys failed. Last: ' + lastErr);
}

// ── MODEL DISCOVERY ──────────────────────────────────────────────────
// Every OpenAI-compatible provider exposes /v1/models. Gemini does not (its
// compat layer 404s), so it uses the native endpoint and a different shape.
function modelsEndpoint(provider, customUrl) {
  switch (provider) {
    case 'groq':       return 'https://api.groq.com/openai/v1/models';
    case 'mistral':    return 'https://api.mistral.ai/v1/models';
    case 'openrouter': return 'https://openrouter.ai/api/v1/models';
    case 'imgxh':      return 'https://imgxh.eu.org/v1/models';
    case 'gemini':     return 'https://generativelanguage.googleapis.com/v1beta/models';
    case 'custom': {
      if (!customUrl) return null;
      // .../v1/chat/completions -> .../v1/models
      try {
        const u = new URL(customUrl);
        u.search = ''; u.hash = '';
        u.pathname = u.pathname.replace(/\/chat\/completions\/?$/, '') .replace(/\/$/, '') + '/models';
        return u.toString();
      } catch { return null; }
    }
    default: return null;   // cloudflare has no catalogue endpoint
  }
}

async function fetchModelList(provider, apiKey, customUrl, env = null) {
  const url = modelsEndpoint(provider, customUrl);
  if (!url) return { models: [], note: provider === 'cloudflare'
    ? 'Cloudflare has no model list - use an @cf/... id from their catalogue.'
    : 'This provider does not publish a model list.' };

  const headers = { 'Accept': 'application/json', 'User-Agent': 'rsroleplay-worker/1.0' };
  let target = url;
  if (provider === 'gemini') target = url + '?key=' + encodeURIComponent(apiKey || '');
  else if (apiKey) headers['Authorization'] = 'Bearer ' + apiKey;

  const res = await providerCall(env, target, { headers }, 15_000);
  if (!res.ok) {
    let body = '';
    try { body = await readBodyWithTimeout(res, 5_000); } catch {}
    throw new Error(`${provider} HTTP ${res.status}: ${body.slice(0, 120)}`);
  }
  const raw = await readBodyWithTimeout(res, 15_000);
  let j; try { j = JSON.parse(raw); } catch { throw new Error('That endpoint did not return JSON'); }

  // OpenAI shape: {data:[{id}]}. Gemini native: {models:[{name:"models/x"}]}.
  const list = Array.isArray(j.data) ? j.data.map(m => m && m.id)
             : Array.isArray(j.models) ? j.models.map(m => String((m && m.name) || '').replace(/^models\//, ''))
             : [];
  /* An id is shown and clicked in the browser, so only plain text gets out:
     a number is written out, anything else is dropped, and nothing is longer
     than a real model id. */
  const ids = list.map(x => (typeof x === 'string' || typeof x === 'number') ? String(x).trim().slice(0, 200) : '');
  return { models: [...new Set(ids.filter(Boolean))].sort() };
}

// -- HISTORY PAGING ---------------------------------------------------
// Reads one page of history plus every variant of the bot messages on it.
// The variants used to be fetched one query per message (up to 50 sequential
// D1 round trips for a single page); they are one batched round trip now, and
// has_more comes from an extra row rather than a second query.
async function fetchHistoryPage(db, sid, limit, beforeTs = 0) {
  const rows = beforeTs > 0
    ? await db.all('SELECT * FROM chat_history WHERE session_id = ? AND is_main = 1 AND timestamp < ? ORDER BY timestamp DESC LIMIT ?', [sid, beforeTs, limit + 1])
    : await db.all('SELECT * FROM chat_history WHERE session_id = ? AND is_main = 1 ORDER BY timestamp DESC LIMIT ?', [sid, limit + 1]);

  const hasMore = rows.length > limit;
  if (hasMore) rows.pop();   // DESC order, so the surplus row is the oldest one
  rows.reverse();

  // The alternative replies. Every row of a group keeps the group's original
  // timestamp (regenerate deliberately reuses it), so one range scan over the
  // (session_id, is_main, timestamp) index picks up every variant on the page.
  // Asking only for is_main = 0 means the rows we are already holding are not
  // read a second time; the old group_id IN (...) form re-read the entire page
  // on top of the variants, roughly doubling the rows this endpoint cost.
  const byGroup = new Map();
  if (rows.some(r => r.role === 'bot')) {
    const extras = await db.all(
      'SELECT id, group_id, content, timestamp FROM chat_history WHERE session_id = ? AND is_main = 0 AND timestamp >= ? AND timestamp <= ? ORDER BY timestamp, id',
      [sid, rows[0].timestamp, rows[rows.length - 1].timestamp]
    );
    for (const v of extras) {
      if (!byGroup.has(v.group_id)) byGroup.set(v.group_id, []);
      byGroup.get(v.group_id).push(v);
    }
  }

  for (const msg of rows) {
    if (msg.role !== 'bot') continue;
    const extras = byGroup.get(msg.group_id);
    if (!extras) {
      msg.variants = [msg.content]; msg.variant_ids = [msg.id]; msg.active_index = 0;
      continue;
    }
    // Reassembled in the (timestamp, id) order the single query used to return.
    const vars = [...extras, { id: msg.id, content: msg.content, timestamp: msg.timestamp, main: true }]
      .sort((a, b) => (a.timestamp - b.timestamp) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
    msg.variants     = vars.map(v => v.content);
    msg.variant_ids  = vars.map(v => v.id);
    msg.active_index = vars.findIndex(v => v.main);
  }

  return { messages: rows, has_more: hasMore };
}

// -- SSE STREAM -------------------------------------------------------
// Design rules, in order of importance:
//   1. Never throw away text we already received. If the upstream provider
//      drops the socket we save the partial reply instead of discarding it.
//   2. If it drops mid-generation, transparently reconnect and ask the model to
//      continue, stitching the halves back together (overlap-deduplicated).
//   3. The browser is only ever a spectator. Frames to it are best-effort and
//      can never slow the upstream read; the reply is checkpointed to the
//      database as it arrives and finished under waitUntil, so a phone with
//      a bad connection - or no connection - still ends up with the full text.
//   4. CPU is the scarce resource. A Free-plan Worker gets 10 ms per request,
//      accrued over the entire stream, so the hot loop does no JSON parsing
//      of provider deltas, writes no per-delta frames and arms no per-read
//      timers (see createUnifiedStream).
const STREAM_FIRST_BYTE_MS = 90_000;  // reasoning models can think a while before the first token
const STREAM_STALL_MS      = 30_000;  // no further bytes for this long => dropped
const STREAM_MAX_RESUMES   = 2;       // reconnect attempts after a mid-reply drop
const STREAM_TOTAL_MS      = 240_000; // hard ceiling on one generation, resumes included
const RESUME_SCAN_CHARS    = 400;     // how much of a resumed reply we inspect for overlap
const FLUSH_MS             = 150;     // outbound frames are coalesced to this cadence...
const FLUSH_CHARS          = 2048;    // ...or sooner once this much text is waiting
const CHECKPOINT_MS        = 2000;    // partial reply -> database: the shortest gap...
const CHECKPOINT_MAX_MS    = 25_000;  // ...the longest, well inside STALL_AFTER_MS...
const CHECKPOINT_BUDGET    = 16;      // ...and how many one reply may write, at most
const STALL_AFTER_MS       = 45_000;  // a 'running' row not checkpointed for this long is dead

// Some providers simply never send [DONE] or a finish_reason. Reconnecting
// twice for every one of those messages would be pure waste, so we only resume
// when the text actually reads as cut off mid-thought.
function looksTruncated(text) {
  const t = text.trimEnd();
  if (!t) return true;
  return !/[.!?\u2026"'\u201d\u2019)\]}*`~\u3002\uff01\uff1f]$/u.test(t);
}

// A resumed generation usually re-emits the tail of what we already have.
// Strip the longest suffix/prefix overlap so the seam is invisible.
function stripOverlap(prev, next) {
  if (!prev || !next) return next;
  const max = Math.min(prev.length, next.length, RESUME_SCAN_CHARS);
  const first = next.charCodeAt(0);
  for (let n = max; n >= 4; n--) {
    if (prev.charCodeAt(prev.length - n) !== first) continue;   // cheap pre-check before slicing
    if (!prev.endsWith(next.slice(0, n))) continue;
    // A long match is unambiguous. A short one only counts when it starts on a
    // word boundary, so we never eat a legitimately repeated fragment.
    if (n >= 12) return next.slice(n);
    const before = prev[prev.length - n - 1];
    if (before === undefined || /[\s\p{P}]/u.test(before)) return next.slice(n);
  }
  return next;
}

// The string value of `"key":"` inside one JSON line, without parsing the
// object. Bounded to [s, e). The key pattern includes its opening quote, so it
// cannot match inside a string value (where quotes are always escaped), and
// `"content":"` cannot match `"reasoning_content":"`. Returns null when the
// key is absent or not a string (e.g. `"content":null`).
function jsonStr(text, keyPat, s, e) {
  const k = text.indexOf(keyPat, s);
  if (k === -1 || k >= e) return null;
  const from = k + keyPat.length;
  let i = from, esc = false;
  for (; i < e; i++) {
    const ch = text.charCodeAt(i);
    if (esc) { esc = false; continue; }
    if (ch === 92) { esc = true; continue; }   // backslash
    if (ch === 34) break;                      // closing quote
  }
  const raw = text.slice(from, i);
  if (raw.indexOf('\\') === -1) return raw;    // no escapes: verbatim
  try { return JSON.parse('"' + raw + '"'); } catch { return null; }
}

/**
 * @param openStream  async (partialSoFar|null) => ReadableStream - called once
 *                    up front, then again for each resume attempt.
 * @param onFinish    async (finalText, hardError, partial, errMsg) => metadata
 * @param onProgress  (textSoFar) => Promise - throttled checkpoint of the
 *                    partial reply. Failures are ignored, calls never overlap,
 *                    and the last one is awaited before onFinish.
 * @param initial     object sent as the very first frame (the saved row ids).
 */
function createUnifiedStream({ openStream, onFinish, onProgress = null, initial = null }) {
  const enc = new TextEncoder();
  let controller = null, clientGone = false;
  // A plain ReadableStream cannot exert backpressure on us: a slow phone just
  // receives bigger frames while the provider is read at full speed. (The old
  // TransformStream writer was awaited, so a stalled browser stalled the
  // upstream read until the provider's idle timeout cut the reply short.)
  const readable = new ReadableStream({
    start(c) { controller = c; },
    cancel()  { clientGone = true; },   // browser went away: keep generating, stop sending
  });
  function emit(str) {
    if (clientGone) return;
    try { controller.enqueue(enc.encode(str)); } catch { clientGone = true; }
  }
  const sendFrame = (obj) => emit('data: ' + JSON.stringify(obj) + '\n\n');

  let content = '', reasoning = '';
  let headBuf = null;      // resume: first RESUME_SCAN_CHARS held back for seam dedupe
  let skipChars = 0;       // resume: characters of a restarted reply still to drop
  let deadline = Infinity;
  let streamError = null;  // an {"error":...} line the provider sent instead of text
  /* finish_reason:"length" nghĩa là hết hạn mức token giữa chừng, không phải
     model đã nói xong. Gemini 2.5 trở lên tính cả token suy nghĩ vào max_tokens
     nên một câu trả lời về code ăn hết 8192 token rồi đứt ngang giữa câu. */
  let hitLimit = false;

  // -- outbound coalescing ----------------------------------------------
  let pendText = '', pendReasoning = '', flushTimer = null;
  function flush() {
    if (flushTimer) { clearTimeout(flushTimer); flushTimer = null; }
    if (!pendText && !pendReasoning) return;
    const f = {};
    if (pendReasoning) { f.reasoning = pendReasoning; pendReasoning = ''; }
    if (pendText)      { f.chunk = pendText;          pendText = ''; }
    sendFrame(f);
  }
  function queue(isText, t) {
    if (isText) pendText += t; else pendReasoning += t;
    if (pendText.length + pendReasoning.length >= FLUSH_CHARS) return flush();
    if (!flushTimer) flushTimer = setTimeout(flush, FLUSH_MS);
  }

  // -- checkpointing ------------------------------------------------------
  let lastCkAt = 0, lastCkLen = -1, ckPromise = null, ckStart = 0, ckCount = 0;
  const compose = (body) => reasoning ? '<think>\n' + reasoning + '\n</think>\n\n' + body : body;
  function maybeCheckpoint() {
    if (!onProgress || ckPromise || ckCount >= CHECKPOINT_BUDGET) return;
    const now = Date.now();
    /* Every checkpoint is two D1 statements, and the Free plan allows 50 per
       request, the final save included. At a flat 2s (1s once the tab had
       closed) a long reply used them all up part-way, and then the final save
       failed too. The gap now widens as the reply goes on: 2s at first, then a
       third of the time elapsed, at most 25s so a browser following along
       still sees it alive (STALL_AFTER_MS). The longest reply allowed, four
       minutes, comes to 16 checkpoints; CHECKPOINT_BUDGET holds it there. */
    if (!ckStart) ckStart = now;
    const gap = Math.min(CHECKPOINT_MAX_MS, Math.max(CHECKPOINT_MS, (now - ckStart) / 3));
    if (now - lastCkAt < gap) return;
    const len = content.length + reasoning.length;
    if (len === lastCkLen || len === 0) return;
    lastCkAt = now; lastCkLen = len; ckCount++;
    // Not awaited: a database round trip must never stall the provider read.
    ckPromise = Promise.resolve().then(() => onProgress(compose(content))).catch(() => {}).then(() => { ckPromise = null; });
  }

  // -- text intake (resume-aware) -----------------------------------------
  function pushText(chunk) {
    if (skipChars > 0) {
      if (chunk.length <= skipChars) { skipChars -= chunk.length; return; }
      chunk = chunk.slice(skipChars); skipChars = 0;
    }
    if (headBuf !== null) {
      headBuf += chunk;
      if (headBuf.length >= RESUME_SCAN_CHARS) absorbHead();
      return;
    }
    content += chunk; queue(true, chunk);
  }
  // Decides what to do with the opening of a resumed reply.
  function absorbHead() {
    const head = headBuf; headBuf = null;
    if (!head) return;
    if (head.length >= 60) {
      // Case 1: the model ignored "continue" and started the reply over. Skip
      // ahead to the point we had already reached instead of duplicating it.
      if (content.startsWith(head)) { skipChars = content.length - head.length; return; }
      if (head.startsWith(content)) {
        const rest = head.slice(content.length);
        if (rest) { content += rest; queue(true, rest); }
        return;
      }
    }
    // Case 2: it repeated only the tail before carrying on.
    const merged = stripOverlap(content, head);
    if (merged) { content += merged; queue(true, merged); }
  }

  // One SSE data payload, text[s, e). Returns true on a finish marker.
  function handleData(text, s, e) {
    if (text.startsWith('[DONE]', s)) return true;
    let got = false;
    const c = jsonStr(text, '"content":"', s, e);
    if (c !== null) { got = true; if (c) pushText(c); }
    let r = jsonStr(text, '"reasoning":"', s, e);
    if (r === null) r = jsonStr(text, '"reasoning_content":"', s, e);
    if (r !== null) { got = true; if (r) { reasoning += r; queue(false, r); } }
    const f = text.indexOf('"finish_reason":"', s);          // a string, i.e. not null
    if (f !== -1 && f < e) {
      if (text.startsWith('"finish_reason":"length"', f)) hitLimit = true;
      return true;
    }
    if (!got) {
      const er = text.indexOf('"error"', s);
      if (er !== -1 && er < e) streamError = text.slice(s, Math.min(e, s + 300));
    }
    return false;
  }

  // Reads one upstream SSE stream. Returns true when the provider signalled a
  // proper finish, false when the socket ended early. Throws on a stall.
  async function pump(rawStream) {
    const reader = rawStream.getReader();
    const dec = new TextDecoder();
    hitLimit = false;
    let tail = '', finished = false, sawBytes = false, stalled = false;
    let lastByteAt = Date.now();
    // One coarse watchdog instead of a fresh timer race per read (which cost
    // a promise + two timer calls for every chunk). Cancelling the reader
    // settles a pending read(), which is how the loop below finds out.
    const watchdog = setInterval(() => {
      const limit = sawBytes ? STREAM_STALL_MS : STREAM_FIRST_BYTE_MS;
      const now = Date.now();
      if (now - lastByteAt > limit || now > deadline) {
        stalled = true;
        try { reader.cancel(); } catch { /* already closed */ }
      }
    }, 5000);
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (stalled) throw new Error(Date.now() > deadline ? 'Generation ran out of time' : 'Upstream stalled');
        let text = '';
        if (value) { sawBytes = true; lastByteAt = Date.now(); text = dec.decode(value, { stream: true }); }
        if (done) text += dec.decode() + '\n';     // flush the decoder, terminate a last line
        if (tail) { text = tail + text; tail = ''; }

        let start = 0, nl;
        while ((nl = text.indexOf('\n', start)) !== -1) {
          let end = nl;
          if (end > start && text.charCodeAt(end - 1) === 13) end--;   // \r
          if (text.startsWith('data:', start)) {
            let p = start + 5;
            while (p < end && text.charCodeAt(p) === 32) p++;
            if (p < end && handleData(text, p, end)) finished = true;
          }
          start = nl + 1;
        }
        if (start < text.length && !done) tail = text.slice(start);
        maybeCheckpoint();
        if (done) break;
      }
    } finally {
      clearInterval(watchdog);
      if (headBuf !== null) absorbHead();
      try { reader.cancel(); } catch { /* already closed */ }
    }
    return finished;
  }

  async function run() {
    let clean = false, lastErr = null;
    deadline = Date.now() + STREAM_TOTAL_MS;
    if (initial) sendFrame(initial);
    // Comment frames keep intermediaries (and mobile networks) from treating a
    // long "thinking" pause as an idle connection and tearing it down.
    const keepAlive = setInterval(() => emit(': ka\n\n'), 10_000);

    try {
      for (let attempt = 0; attempt <= STREAM_MAX_RESUMES; attempt++) {
        if (Date.now() >= deadline) { lastErr = lastErr ?? new Error('Generation ran out of time'); break; }
        const lengthBefore = content.length;
        let raw;
        try {
          raw = await openStream(attempt === 0 ? null : content);
        } catch (e) {
          lastErr = e;
          if (attempt === 0) break;      // never even connected; nothing to resume
          continue;
        }
        if (!raw) { lastErr = lastErr ?? new Error('Upstream returned no stream'); continue; }

        if (attempt > 0) {
          headBuf = '';                  // dedupe the seam of the resumed reply
          flush();
          sendFrame({ resumed: true });
        }

        try {
          if (await pump(raw)) {
            // Hết hạn mức token thì nối tiếp bằng chính cơ chế resume ở trên,
            // thay vì giao cho người dùng một đoạn code đứt giữa dòng.
            if (!hitLimit) { clean = true; break; }
            lastErr = new Error('The reply reached the token limit');
          } else {
            lastErr = new Error(streamError ? 'Upstream error: ' + streamError : 'Upstream closed the stream before finishing');
            // No finish marker, but the text reads as complete: accept it rather
            // than spending two more requests on a provider that never sends [DONE].
            if (!looksTruncated(content)) { clean = true; break; }
          }
        } catch (e) {
          lastErr = e;
        }

        // Nothing at all came back. executeLLM has already failed over across
        // every configured key, so a reconnect would just spend another
        // first-byte timeout holding a socket open - the very thing that used
        // to leave an isolate wedged for five minutes per attempt.
        if (content.length === 0) break;
        // A resume that produced nothing means the model has nothing left to add.
        if (attempt > 0 && content.length === lengthBefore) break;
      }
    } finally {
      clearInterval(keepAlive);
      flush();
      if (ckPromise) await ckPromise;    // never let a late checkpoint overwrite the final text

      const body = content.indexOf('<thought>') === -1 ? content
        : content.replace(/<thought>/gi, '<think>').replace(/<\/thought>/gi, '</think>');
      const finalOutput = compose(body);

      // Only a reply with zero text is a hard failure. Anything else gets saved.
      const hardError = !clean && body.trim().length === 0;
      const partial   = !clean && !hardError;

      let meta = {};
      try {
        meta = (await onFinish(finalOutput, hardError, partial, lastErr?.message ?? null)) ?? {};
      } catch (e) {
        lastErr = e;
        if (!hardError) sendFrame({ warning: 'Reply received but could not be saved: ' + e.message });
      }

      if (hardError) sendFrame({ error: lastErr?.message || 'Upstream connection failed', ...meta });
      else           sendFrame({ done: true, partial, ...meta });
      try { controller.close(); } catch { /* client gone */ }
    }
  }

  return { readable, done: run() };
}


// ── CURSOR RESOLVER ──────────────────────────────────────────────────
// Turns a pasted cursor-page URL into ready-to-use images. Runs only when
// a signed-in user asks for it, one page at a time.
const CURSOR_MAX_BYTES = 262144;   // a cursor is ~1-40KB; anything bigger is not one
const CURSOR_MAX_PAGE  = 786432;   // stop reading a page after this
const CURSOR_MAX_PICKS = 12;
const CURSOR_TYPES = new Set(['image/png','image/gif','image/webp','image/jpeg','image/svg+xml','image/x-icon','image/vnd.microsoft.icon']);

// Only public https origins. Blocks the usual SSRF targets plus anything
// that is a bare IP, since a hostname is what a real cursor site has.
function safeCursorURL(raw) {
  let u;
  try { u = new URL(raw); } catch { throw new Error('That does not look like a link'); }
  if (u.protocol !== 'https:' && u.protocol !== 'http:') throw new Error('Only http(s) links work');
  const h = u.hostname.toLowerCase();
  if (h === 'localhost' || h.endsWith('.localhost') || h.endsWith('.internal') ||
      /^\d{1,3}(\.\d{1,3}){3}$/.test(h) || h.includes(':') ||
      h === '0.0.0.0' || h === 'metadata.google.internal') {
    throw new Error('That address is not allowed');
  }
  return u;
}

const CURSOR_FETCH_HEADERS = {
  'User-Agent': 'Mozilla/5.0 (compatible; rsroleplay-cursor/1.0)',
  'Accept': 'text/html,image/*;q=0.9,*/*;q=0.8',
};

async function fetchCursorImage(url) {
  const res = await fetchWithTimeout(url, { headers: CURSOR_FETCH_HEADERS, redirect: 'follow' }, 12_000, null);
  if (!res.ok) return null;
  const type = (res.headers.get('Content-Type') || '').split(';')[0].trim().toLowerCase();
  if (!CURSOR_TYPES.has(type)) { try { await res.body?.cancel(); } catch {} return null; }
  const len = Number(res.headers.get('Content-Length') || 0);
  if (len > CURSOR_MAX_BYTES) { try { await res.body?.cancel(); } catch {} return null; }
  const buf = new Uint8Array(await res.arrayBuffer());
  if (buf.length === 0 || buf.length > CURSOR_MAX_BYTES) return null;
  let bin = '';
  for (let i = 0; i < buf.length; i += 8192) bin += String.fromCharCode(...buf.subarray(i, i + 8192));
  return { url, type, bytes: buf.length, dataUri: `data:${type};base64,${btoa(bin)}` };
}

// Per-site rules. Each returns candidate IMAGE urls for a page url, or null
// to fall through to the generic scraper.
function cursorSiteRules(u) {
  const host = u.hostname.replace(/^www\./, '');
  const path = u.pathname;

  if (host === 'rw-designer.com') {
    // /cursor-detail/257548 -> the clean art, NOT /cursor-view (crosshair)
    const one = path.match(/\/cursor-(?:detail|view|image)\/(\d+)/);
    if (one) return [`https://www.rw-designer.com/cursor-image/${one[1]}-32x32.png`];
    return null;                      // a set page: let the generic pass find every id
  }
  return null;
}

// Rewrites an image url the generic pass found, when the site is known to
// serve a better version at a sibling path.
function cursorPreferredVariant(u, imgUrl) {
  if (u.hostname.replace(/^www\./, '') === 'rw-designer.com') {
    const m = imgUrl.match(/\/cursor-view\/(\d+)\.png/);
    if (m) return `https://www.rw-designer.com/cursor-image/${m[1]}-32x32.png`;
  }
  return imgUrl;
}

// Streaming HTML scan. HTMLRewriter is the Workers-native parser: it never
// materialises the document, so this costs a fraction of a regex pass over
// a 200KB page.
async function scrapeCursorCandidates(u) {
  const res = await fetchWithTimeout(u.toString(), { headers: CURSOR_FETCH_HEADERS, redirect: 'follow' }, 12_000, null);
  if (!res.ok) throw new Error(`That page answered ${res.status}`);
  const type = (res.headers.get('Content-Type') || '').split(';')[0].trim().toLowerCase();

  if (CURSOR_TYPES.has(type)) return { direct: true, urls: [u.toString()] };
  if (!type.startsWith('text/html')) throw new Error('That link is not a page or an image');

  const meta = [], imgs = [];
  let seen = 0;
  const abs = (v) => { try { return new URL(v, u).toString(); } catch { return null; } };

  const rewriter = new HTMLRewriter()
    .on('meta[property="og:image"], meta[name="og:image"], meta[property="og:image:secure_url"]', {
      element(el) { const v = abs(el.getAttribute('content')); if (v) meta.push(v); },
    })
    .on('link[rel="image_src"]', {
      element(el) { const v = abs(el.getAttribute('href')); if (v) meta.push(v); },
    })
    .on('img', {
      element(el) {
        if (imgs.length >= 60) return;
        const v = abs(el.getAttribute('src') || el.getAttribute('data-src'));
        if (!v) return;
        const w = parseInt(el.getAttribute('width') || '0', 10);
        // a cursor preview is small and square-ish; skip banners and avatars
        if (w > 256) return;
        if (!/\.(png|gif|webp|cur|ani|ico)(\?|$)/i.test(v) && !/cursor/i.test(v)) return;
        imgs.push(v);
      },
    });

  // Drain through the rewriter so the handlers run, with a page-size cap.
  const out = rewriter.transform(res).body;
  const reader = out.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    seen += value.length;
    if (seen > CURSOR_MAX_PAGE) { try { await reader.cancel(); } catch {} break; }
  }

  // Prefer explicit cursor art, then social preview, then anything cursor-ish.
  const ranked = [];
  const push = (v) => { const p = cursorPreferredVariant(u, v); if (p && !ranked.includes(p)) ranked.push(p); };
  meta.forEach(push);                                   // og:image = this page's own art
  imgs.filter(v => /cursor-image/i.test(v)).forEach(push);
  imgs.filter(v => /cursor/i.test(v)).forEach(push);
  imgs.forEach(push);
  if (!ranked.length) throw new Error('No cursor image found on that page');
  return { direct: false, urls: ranked.slice(0, CURSOR_MAX_PICKS) };
}

// -- GENERATION JOBS --------------------------------------------------
function trackGeneration(db, sid, botId, groupId) {
  return [
    // One tracking row per session, so a browser that reconnects (or a brand
    // new tab) can ask what became of the reply it stopped seeing.
    db.d1.prepare('DELETE FROM active_generations WHERE session_id = ?').bind(sid),
    db.d1.prepare('INSERT INTO active_generations (bot_id, session_id, group_id, state, error, updated_at) VALUES (?, ?, ?, ?, ?, ?)')
      .bind(botId, sid, groupId, 'running', null, Date.now()),
  ];
}

// A message is written to the database BEFORE anything talks to a provider.
// From that point on nothing downstream - the provider, the stream, the
// browser's connection, the Worker being stopped - can cost the user what they
// typed, and the empty reply row is what Retry and follow-along hang off.
async function reserveTurn(db, sid, content) {
  const userTs  = Date.now();
  const userId  = generateId();
  const botId   = generateId();
  const groupId = 'g_' + generateId();
  const ins = 'INSERT INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)';
  await db.d1.batch([
    db.d1.prepare(ins).bind(userId, sid, 'g_' + generateId(), 1, 'user', content, userTs),
    db.d1.prepare(ins).bind(botId, sid, groupId, 1, 'bot', '', userTs + 1),
    ...trackGeneration(db, sid, botId, groupId),
  ]);
  return { user_id: userId, bot_id: botId, group_id: groupId };
}

// Partial reply -> database, a handful of times while the reply streams (see
// maybeCheckpoint for when), so a Worker stopped mid-reply (CPU limit,
// eviction, the tab closing and waitUntil running out) loses only the text
// written since the last one.
function checkpointReply(db, botId, text) {
  return db.d1.batch([
    db.d1.prepare('UPDATE chat_history SET content = ? WHERE id = ?').bind(text, botId),
    db.d1.prepare('UPDATE active_generations SET updated_at = ? WHERE bot_id = ?').bind(Date.now(), botId),
  ]);
}

function markGeneration(db, botId, state, error = null) {
  return db.run('UPDATE active_generations SET state = ?, error = ?, updated_at = ? WHERE bot_id = ?',
    [state, error ? String(error).slice(0, 500) : null, Date.now(), botId]).catch(() => {});
}

// Called once with null, then again for each reconnect attempt after a
// mid-reply drop. On a reconnect the model gets what it already produced and
// is asked to carry on from there.
function makeOpenStream(apiKeys, ctxMsgs, thinkingEffort, gen, firstStream) {
  return async (partial) => {
    if (!partial) {
      if (firstStream) { const s = firstStream; firstStream = null; return s; }
      return (await executeLLM(apiKeys, ctxMsgs, 'chat', thinkingEffort, true, null, gen)).stream;
    }
    const resumeMsgs = [...ctxMsgs, { role: 'assistant', content: partial }, { role: 'user', content: CONTINUE_PROMPT }];
    return (await executeLLM(apiKeys, resumeMsgs, 'chat', thinkingEffort, true, null, gen)).stream;
  };
}

// The reply for a turn reserved by reserveTurn. Returns { json } when there is
// nothing to stream (the provider never opened), else { readable, done }.
async function runSendJob(db, job) {
  const { sid, turn, thinkingEffort } = job;
  // The user's message is already in the history, so nothing is appended.
  const [built, cfg] = await Promise.all([buildCtx(sid, null, db, null, null), loadKeysAndGen(db)]);
  const { msgs: ctxMsgs, mem } = built;
  const { apiKeys, gen } = cfg;

  let firstStream;
  try {
    firstStream = (await executeLLM(apiKeys, ctxMsgs, 'chat', thinkingEffort, true, null, gen)).stream;
  } catch (e) {
    // Re-read api_keys / gen_settings next time rather than trusting this
    // isolate's copy, so fixing a broken key takes effect immediately.
    cacheDrop('cfg');
    if (e.isGeminiDebug) {
      const errText = '\u26a0\ufe0f **Gemini API Error**\n\n```\n' + e.message + '\n```';
      await db.run('UPDATE chat_history SET content = ? WHERE id = ?', [errText, turn.bot_id]);
      await markGeneration(db, turn.bot_id, 'error', e.message);
      return { json: { gemini_error: true, ...turn, content: errText } };
    }
    await markGeneration(db, turn.bot_id, 'error', e.message);
    // 200 with the error in the payload: a 5xx would make the browser retry
    // and reserve the same turn again.
    return { json: { upstream_error: true, error: e.message, ...turn } };
  }

  return createUnifiedStream({
    openStream: makeOpenStream(apiKeys, ctxMsgs, thinkingEffort, gen, firstStream),
    initial:    { saved: turn },
    onProgress: (text) => checkpointReply(db, turn.bot_id, text),
    onFinish:   async (finalText, hardError, partial, errMsg) => {
      if (hardError) { cacheDrop('cfg'); await markGeneration(db, turn.bot_id, 'error', errMsg); return turn; }
      const lastTs    = mem.last_summarized_timestamp ?? 0;
      const threshold = Math.max(1, mem.summarize_threshold ?? 50);
      const res = await db.d1.batch([
        db.d1.prepare('UPDATE chat_history SET content = ? WHERE id = ?').bind(finalText, turn.bot_id),
        db.d1.prepare('UPDATE active_generations SET state = ?, updated_at = ? WHERE bot_id = ?')
          .bind(partial ? 'partial' : 'done', Date.now(), turn.bot_id),
        // Stops counting once the threshold is reached, rather than scanning
        // the whole session on every send.
        db.d1.prepare('SELECT COUNT(*) AS c FROM (SELECT 1 FROM chat_history WHERE session_id = ? AND is_main = 1 AND timestamp > ? LIMIT ?)')
          .bind(sid, lastTs, threshold),
      ]);
      const seen = res[2].results?.[0]?.c ?? 0;
      return { ...turn, should_summarize: seen >= threshold };
    },
  });
}

// A new variant for an existing reply. Failing outright leaves the history
// untouched: the variant row only comes into being once real text exists, and
// from then on it is checkpointed like any other reply.
async function runRegenJob(db, job) {
  const { sid, oldMsg } = job;
  const groupId = oldMsg.group_id;
  const [built, cfg] = await Promise.all([buildCtx(sid, null, db, oldMsg.timestamp, null), loadKeysAndGen(db)]);
  const ctxMsgs = built.msgs;
  const { apiKeys, gen } = cfg;

  let firstStream;
  try {
    firstStream = (await executeLLM(apiKeys, ctxMsgs, 'chat', 'none', true, null, gen)).stream;
  } catch (e) {
    cacheDrop('cfg');
    return { json: { error: e.message }, status: 500 };
  }

  let botId = null;
  const upsert = (text) => {
    if (botId) return checkpointReply(db, botId, text);
    botId = generateId();
    return db.d1.batch([
      db.d1.prepare('UPDATE chat_history SET is_main = 0 WHERE group_id = ?').bind(groupId),
      // Clear out the empty row a failed send left behind, so nobody ends up
      // with a blank variant to swipe back through.
      db.d1.prepare("DELETE FROM chat_history WHERE group_id = ? AND role = 'bot' AND TRIM(content) = ''").bind(groupId),
      db.d1.prepare('INSERT INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)')
        // Reuse the old timestamp to prevent context jumping.
        .bind(botId, sid, groupId, 1, 'bot', text, oldMsg.timestamp),
      ...trackGeneration(db, sid, botId, groupId),
    ]);
  };

  return createUnifiedStream({
    openStream: makeOpenStream(apiKeys, ctxMsgs, 'none', gen, firstStream),
    onProgress: upsert,
    onFinish:   async (finalText, hardError, partial) => {
      if (hardError) { cacheDrop('cfg'); return {}; }   // keep the existing variant untouched
      await upsert(finalText);
      await markGeneration(db, botId, partial ? 'partial' : 'done');
      return { bot_id: botId, group_id: groupId, content: finalText };
    },
  });
}

async function finishGeneration(db, job, ctx) {
  const r = job.kind === 'regen' ? await runRegenJob(db, job) : await runSendJob(db, job);
  if (r.json) return jsonResponse(r.json, r.status ?? 200);
  // Keep draining and saving even if the browser drops the connection.
  ctx?.waitUntil?.(r.done);
  return new Response(r.readable, { headers: SSE_HEADERS });
}

// Runs a job where the CPU budget allows. With the STREAMER Durable Object
// bound, the Worker hands the job over and returns the object's response as
// its own: the bytes are piped natively, so the Worker spends no CPU on the
// stream, while the object carries it under its own 30 s budget, unlimited
// wall time, and its own waitUntil for finishing after the browser leaves.
// Without the binding the very same code runs here, inside the Worker's 10 ms.
function dispatchGeneration(env, ctx, db, job) {
  if (env.STREAMER) {
    const stub = env.STREAMER.get(env.STREAMER.idFromName(job.sid));
    return stub.fetch('https://streamer/generate', { method: 'POST', body: JSON.stringify(job) });
  }
  return finishGeneration(db, job, ctx);
}

// ── STREAMING DURABLE OBJECT ─────────────────────────────────────────
// One per chat session. SQLite-backed objects are on the Free plan and get
// 30 seconds of CPU per request where the Worker gets 10 ms - the difference
// between a long reply finishing and being killed part-way through.
export class ChatStreamer {
  constructor(state, env) { this.state = state; this.env = env; ENV = env; }

  async fetch(request) {
    /* Hỏi nhà cung cấp hộ Worker. Worker chạy tại colo mà trình duyệt vào, và
       một số colo nằm ở nơi Google không phục vụ; Durable Object thì được ghim
       vùng lúc tạo (xem PROBE_LOCATION), nên hỏi từ đây mới có câu trả lời ổn
       định. Chỉ mã của chính Worker này gọi tới được, không mở ra ngoài. */
    if (new URL(request.url).pathname === '/probe') {
      const { url, init, ms } = await request.json();
      try {
        const res = await fetchWithTimeout(url, init, ms || 20_000, null);
        /* Chuyển tiếp nguyên dòng dữ liệu, không đọc hết thành chữ: một câu trả
           lời đang được viết dần phải chảy qua đây từng mẩu, đúng như khi Worker
           tự gọi. Đọc hết rồi mới trả là mất cả cơ chế hiện chữ dần. */
        return new Response(res.body, {
          status: res.status,
          headers: { 'content-type': res.headers.get('content-type') || 'application/json' },
        });
      } catch (e) {
        // 599 không phải mã của nhà cung cấp, nên chỗ gọi phân biệt được đây là
        // "không với tới được" chứ không phải "nhà cung cấp trả lời như vậy".
        return new Response(e.message, { status: 599 });
      }
    }

    const job = await request.json();
    const db  = new DB(this.env.DB);
    // Watchdog: should this object be evicted mid-reply, the alarm still fires
    // and marks the generation stalled so a following browser stops waiting.
    try { await this.state.storage.setAlarm(Date.now() + STREAM_TOTAL_MS + 60_000); } catch { /* storage unavailable */ }
    return finishGeneration(db, job, this.state);
  }

  async alarm() {
    const db = new DB(this.env.DB);
    await db.run("UPDATE active_generations SET state = 'stalled', updated_at = ? WHERE state = 'running' AND updated_at < ?",
      [Date.now(), Date.now() - STALL_AFTER_MS]).catch(() => {});
  }
}

// ── MAIN ROUTER ──────────────────────────────────────────────────────
export default {
  // Daily housekeeping, fired by the cron trigger in wrangler.toml (harmless
  // if it never fires). Small tables keep every lookup above fast.
  async scheduled(controller, env, ctx) {
    ENV = env;
    if (!env.DB) return;
    const db = new DB(env.DB), now = Date.now();
    await db.d1.batch([
      db.d1.prepare('DELETE FROM active_generations WHERE updated_at < ?').bind(now - 86_400_000),
      db.d1.prepare('DELETE FROM user_sessions WHERE expires_at < ?').bind(now),
      db.d1.prepare('DELETE FROM ip_blocks WHERE locked_until IS NULL OR locked_until < ?').bind(now),
    ]);
  },

  async fetch(request, env, ctx) {
    ENV = env;
    if (!env.DB) {
      return new Response('D1 database binding "DB" not found. Check your Cloudflare settings.', { status: 500 });
    }

    const db     = new DB(env.DB);
    const url    = new URL(request.url);
    const action = url.searchParams.get('action');

    // Schema check is memoised per isolate (see ensureSchema).
    await ensureSchema(db);

    let body = {};
    if (request.method === 'POST') {
      try {
        const text = await request.text();
        if (text.length > 1_000_000) return errResponse('Request too large', 413);
        body = JSON.parse(text);
        if (typeof body !== 'object' || Array.isArray(body)) return errResponse('Invalid JSON body', 400);
      } catch { return errResponse('Invalid JSON body', 400); }
    }

    if (!action) {
      // The shell is static, so repeat visits can be answered with a 304
      // instead of re-sending ~180 KB of HTML. Only the "users exist" result is
      // cached (it never goes back to false), so pre-setup stays correct.
      if (!_hasUsers) _hasUsers = (await db.all('SELECT id FROM users LIMIT 1')).length > 0;

      const etag = `W/"${_hasUsers ? 'app' : 'setup'}-${APP_BUILD}"`;
      if (request.headers.get('If-None-Match') === etag) {
        return new Response(null, { status: 304, headers: { 'ETag': etag, 'Cache-Control': HTML_CACHE_CONTROL } });
      }
      // Build the string once per isolate rather than once per request.
      if (_hasUsers) _appHTML ??= getAppHTML();
      else           _setupHTML ??= getSetupHTML();

      return new Response(_hasUsers ? _appHTML : _setupHTML, {
        headers: {
          'Content-Type':  'text/html;charset=utf-8',
          'ETag':          etag,
          'Cache-Control': HTML_CACHE_CONTROL,
          ...SECURITY_HEADERS,
        },
      });
    }

    // ── STATIC ASSETS ────────────────────────────────────────────
    // Immutable per build, so the colo cache answers almost every hit and
    // the Worker spends no CPU on them at all.
    if (action === 'asset') {
      const file = url.searchParams.get('f');
      const bodies = {
        'theme.css':   ['text/css; charset=utf-8', getThemeCSS],
        'bubbles.css': ['text/css; charset=utf-8', getBubbleCSS],
        'bubbles.json':['application/json; charset=utf-8', () => BUBBLE_JSON],
        'tailwind.css':['text/css; charset=utf-8', getTailwindCSS],
        'manifest.webmanifest':['application/manifest+json; charset=utf-8', getManifest],
        'icon.svg':   ['image/svg+xml; charset=utf-8', getAppIcon],
        'icon-192.png':        ['image/png', () => pngBytes(ICON_192)],
        'icon-512.png':        ['image/png', () => pngBytes(ICON_512)],
        'icon-maskable.png':   ['image/png', () => pngBytes(ICON_MASK_512)],
      };
      const entry = bodies[file];
      if (!entry) return errResponse('Unknown asset', 404);

      const key = new Request(new URL(`/__asset/${file}?v=${APP_BUILD}`, url.origin).toString(), { method: 'GET' });
      const cache = caches.default;
      const hit = await cache.match(key);
      if (hit) return hit;

      const res = new Response(entry[1](), {
        headers: {
          'Content-Type': entry[0],
          'Cache-Control': 'public, max-age=31536000, immutable',
          ...SECURITY_HEADERS,
        },
      });
      ctx?.waitUntil?.(cache.put(key, res.clone()));
      return res;
    }

    // ── SETUP ────────────────────────────────────────────────────
    if (action === 'setup' && request.method === 'POST') {
      const existing = await db.all('SELECT id FROM users LIMIT 1');
      if (existing.length > 0) return errResponse('Already set up', 403);

      const username = str(body.username, 64);
      const password = str(body.password, 128);
      const confirm  = str(body.confirm,  128);
      if (!username)                  return errResponse('Invalid username');
      if (!password || password.length < 6) return errResponse('Password must be at least 6 characters');
      if (password !== confirm)       return errResponse('Passwords do not match');

      const { hash, salt } = await pbkdf2(password);
      const userId = generateId();
      await db.insert('users', { id: userId, username, password_hash: hash, salt, created_at: Date.now() });
      _hasUsers = true;

      const personaId = generateId();
      await db.insert('personas', {
        id: personaId, name: 'System Assistant', avatar: 'AI',
        description: 'A helpful AI.', system_prompt: 'You are a helpful, concise assistant.',
        user_persona: 'The user is a developer.', greeting_message: 'Hello! How can I help?',
      });
      await db.insert('chat_sessions', { id: 'default', label: 'Default Session', persona_id: null, created_at: Date.now() });
      await db.insert('chat_history', {
        id: generateId(), session_id: 'default', group_id: 'g_' + generateId(),
        is_main: 1, role: 'bot', content: 'Hello! How can I help?', timestamp: Date.now(),
      });
      await db.insert('memory_state', {
        id: 'global', session_id: 'global', summarize_threshold: 50, summarize_count: 30,
        context_count: 20, history_fetch_count: 50, include_old_summary: 1,
        last_summarized_timestamp: 0, sketchboard_active: 1, current_summary: null,
      });
      return jsonResponse({ success: true });
    }

    // ── LOGIN ────────────────────────────────────────────────────
    if (action === 'login' && request.method === 'POST') {
      const block = await checkBlock(request, db);
      if (block) return errResponse(block, 429);

      const username = str(body.username, 64);
      const password = str(body.password, 128);
      if (!username || !password) return errResponse('Invalid credentials', 401);

      const user = await db.findOne('users', { username });

      /* A missing user used to return before PBKDF2 ran, which made "no such
         name" a measurably cheaper request than "wrong password". Hash against
         a throwaway salt instead, so both answers cost the same. */
      const valid = user
        ? await verifyPassword(password, user.password_hash, user.salt)
        : (await pbkdf2(password, '00000000000000000000000000000000'), false);
      if (!user || !valid) { await failLogin(request, db); return errResponse('Invalid credentials', 401); }

      /* Second factor, if this account has one. The password being right is
         reported the same way whether or not the code is: the response says
         only that a code is needed, never that the password was accepted. */
      if (user.totp_enabled) {
        /* A lock is checked before the code is even looked at, so waiting it
           out is the only way through and guessing during it costs nothing. */
        const lockedFor = (user.mfa_locked_until || 0) - Date.now();
        if (lockedFor > 0) return jsonResponse({ mfa_required: true, error: MFA_RETRY }, 401);

        const code = str(body.code, 32);
        if (!code) return jsonResponse({ mfa_required: true }, 401);

        let step = await totpVerify(user.totp_secret, code, user.totp_last_step || 0);
        let ok = false;
        if (step) {
          await mfaPass(db, user, { totp_last_step: step });
          ok = true;
        } else {
          /* a recovery code, which is spent on use */
          const stored = JSON.parse(user.recovery_codes || '[]');
          const given = await hashRecovery(code, user.salt);
          const idx = stored.indexOf(given);
          if (idx >= 0) {
            stored.splice(idx, 1);
            await mfaPass(db, user, { recovery_codes: JSON.stringify(stored) });
            ok = true;
          }
        }

        if (!ok) {
          /* The ladder still advances, and may still delete the account - it
             just does not say so. Whether this was the first wrong code, the
             one that started a lock, or the one that removed the account, the
             answer looks the same from outside. */
          await mfaFail(db, user);
          await failLogin(request, db);
          return jsonResponse({ mfa_required: true, error: MFA_RETRY }, 401);
        }
      }

      await clearBlock(request, db);
      await db.run('DELETE FROM user_sessions WHERE expires_at < ?', [Date.now()]);

      const token      = crypto.randomUUID();
      const csrf_token = crypto.randomUUID();
      await db.insert('user_sessions', {
        id: generateId(), user_id: user.id, session_token: token, csrf_token,
        expires_at: Date.now() + 30 * 24 * 60 * 60 * 1000, created_at: Date.now(),
      });
      return jsonResponse({ success: true, csrf_token, username: user.username }, 200, {
        'Set-Cookie': `rsroleplay_sess=${token}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=${30 * 24 * 3600}`,
      });
    }

    // ── AUTH WALL ────────────────────────────────────────────────
    const sessionDoc = await auth(request, db);
    if (!sessionDoc) return errResponse('Unauthorized', 401);

    // ── TWO-FACTOR MANAGEMENT ─────────────────────
    if (action === 'mfa') {
      const me = await db.findOne('users', { id: sessionDoc.user_id });
      if (!me) return errResponse('Unauthorized', 401);
      const op = str(body.op, 24) ?? str(url.searchParams.get('op'), 24);

      if (op === 'status') {
        return jsonResponse({
          enabled: !!me.totp_enabled,
          recovery_left: me.totp_enabled ? JSON.parse(me.recovery_codes || '[]').length : 0,
        });
      }

      /* A fresh secret is minted and stored but NOT switched on. It only
         counts once the reader proves their app has it, which is what stops
         an account being locked behind a secret that never got scanned. */
      if (op === 'begin' && request.method === 'POST') {
        if (me.totp_enabled) return errResponse('Already on', 400);
        const secret = base32Encode(crypto.getRandomValues(new Uint8Array(20)));
        await db.update('users', { id: me.id }, { totp_secret: secret, totp_enabled: 0 });
        const label = encodeURIComponent('RSROLEPLAY:' + me.username);
        return jsonResponse({
          secret,
          uri: `otpauth://totp/${label}?secret=${secret}&issuer=RSROLEPLAY&algorithm=SHA1&digits=6&period=30`,
        });
      }

      if (op === 'enable' && request.method === 'POST') {
        if (!me.totp_secret) return errResponse('Start again', 400);
        const step = await totpVerify(me.totp_secret, str(body.code, 32), 0);
        if (!step) return errResponse('That code did not match', 400);
        const codes = newRecoveryCodes();
        const hashed = [];
        for (const c of codes) hashed.push(await hashRecovery(c, me.salt));
        await db.update('users', { id: me.id }, {
          totp_enabled: 1, totp_last_step: step, recovery_codes: JSON.stringify(hashed),
        });
        /* the only time the codes exist in readable form */
        return jsonResponse({ success: true, recovery: codes });
      }

      /* Turning it off asks for the password as well as a code: a borrowed
         open session should not be enough to remove the second factor. */
      if (op === 'disable' && request.method === 'POST') {
        const pw = str(body.password, 128);
        if (!pw || !(await verifyPassword(pw, me.password_hash, me.salt))) {
          return errResponse('Password does not match', 403);
        }
        if (me.totp_enabled) {
          const ok = await totpVerify(me.totp_secret, str(body.code, 32), me.totp_last_step || 0);
          if (!ok) return errResponse('That code did not match', 400);
        }
        await db.update('users', { id: me.id }, {
          totp_enabled: 0, totp_secret: null, totp_last_step: 0, recovery_codes: null,
        });
        return jsonResponse({ success: true });
      }

      if (op === 'regen' && request.method === 'POST') {
        if (!me.totp_enabled) return errResponse('Not on', 400);
        const ok = await totpVerify(me.totp_secret, str(body.code, 32), me.totp_last_step || 0);
        if (!ok) return errResponse('That code did not match', 400);
        const codes = newRecoveryCodes();
        const hashed = [];
        for (const c of codes) hashed.push(await hashRecovery(c, me.salt));
        await db.update('users', { id: me.id }, { recovery_codes: JSON.stringify(hashed), totp_last_step: ok });
        return jsonResponse({ success: true, recovery: codes });
      }

      return errResponse('Unknown operation', 400);
    }

    if (request.method === 'POST') {
      const providedCsrf = request.headers.get('X-CSRF-Token');
      if (!providedCsrf || sessionDoc.csrf_token !== providedCsrf) {
        return errResponse('CSRF validation failed', 403);
      }
    }

    const rawSid = request.headers.get('X-Session-Id') ?? url.searchParams.get('session_id') ?? 'default';
    const sid    = str(rawSid, 100) ?? 'default';
    const userId = sessionDoc.user_id;

    try {
      switch (action) {
case 'branchChat': {
          const targetId = str(body.target_msg_id, 100);
          const newLabel = str(body.new_label, 100) || 'Branched Chat';
          if (!targetId) return errResponse('Invalid target message');

          const targetMsg = await db.findOne('chat_history', { id: targetId });
          if (!targetMsg) return errResponse('Not found', 404);
          if (targetMsg.session_id !== sid) return errResponse('Forbidden', 403);

          const history = await db.all('SELECT * FROM chat_history WHERE session_id = ? AND is_main = 1 AND timestamp <= ? ORDER BY timestamp ASC', [sid, targetMsg.timestamp]);
          
          const newSessionId = generateId();
          const curSess = await db.findOne('chat_sessions', { id: sid });
          
          // 1. Create the new session
          await db.insert('chat_sessions', { id: newSessionId, label: newLabel, persona_id: curSess?.persona_id ?? null, created_at: Date.now() });

          // 2. Clone memory state rules (but reset the current summary)
          const mem = await getMem(sid, db, ctx);
          await db.insert('memory_state', {
            id: generateId(), session_id: newSessionId, summarize_threshold: mem.summarize_threshold,
            summarize_count: mem.summarize_count, context_count: mem.context_count,
            history_fetch_count: mem.history_fetch_count, include_old_summary: mem.include_old_summary,
            last_summarized_timestamp: 0, sketchboard_active: mem.sketchboard_active, current_summary: null
          });

          // 3. Batch insert messages (CRITICAL: chunked by 100 to avoid Cloudflare D1 batch limits)
          const stmts = [];
          for (const msg of history) {
            stmts.push(db.d1.prepare('INSERT INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)')
              .bind(generateId(), newSessionId, 'g_' + generateId(), 1, msg.role, msg.content, msg.timestamp));
          }
          for (let i = 0; i < stmts.length; i += 100) {
            await db.d1.batch(stmts.slice(i, i + 100));
          }

          // 4. Clone active sketchboard pins
          const pins = await db.all('SELECT * FROM sketchboard WHERE session_id = ? AND is_active = 1', [sid]);
          const pinStmts = [];
          for (const p of pins) {
             pinStmts.push(db.d1.prepare('INSERT INTO sketchboard (id, session_id, content, is_active, created_at) VALUES (?, ?, ?, ?, ?)')
               .bind(generateId(), newSessionId, p.content, 1, p.created_at));
          }
          if (pinStmts.length > 0) await db.d1.batch(pinStmts);

          return jsonResponse({ success: true, session_id: newSessionId, label: newLabel });
        }
case 'logout': {
          // Nuke ALL sessions for this user across all devices
          await db.delete('user_sessions', { user_id: userId });
          cacheDrop('auth:');
          return jsonResponse({ success: true }, 200, {
            'Set-Cookie': 'rsroleplay_sess=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0',
          });
        }

        case 'bootstrap': {
          // Everything the app needs at boot in ONE http request and two
          // batched D1 round trips. Both memory rows come from one statement,
          // the current session is picked out of the session list instead of
          // being queried a second time, and personas come from the isolate
          // cache whenever it is warm.
          let personas = cacheGet('personas');
          const stmts  = [];
          const at     = {};
          at.mem      = stmts.push(db.d1.prepare(MEM_PAIR_SQL).bind(sid)) - 1;
          at.sessions = stmts.push(db.d1.prepare('SELECT id, label, persona_id, created_at FROM chat_sessions ORDER BY created_at')) - 1;
          at.user     = stmts.push(db.d1.prepare('SELECT username FROM users WHERE id = ? LIMIT 1').bind(userId)) - 1;
          at.pins     = stmts.push(db.d1.prepare('SELECT * FROM sketchboard WHERE session_id = ? ORDER BY created_at DESC').bind(sid)) - 1;
          at.gen      = stmts.push(db.d1.prepare('SELECT * FROM gen_settings WHERE id = ? LIMIT 1').bind('global')) - 1;
          if (!personas) at.personas = stmts.push(db.d1.prepare('SELECT * FROM personas ORDER BY id')) - 1;

          const res = await db.d1.batch(stmts);
          if (!personas) personas = cacheSet('personas', res[at.personas].results ?? []);

          const memRows = res[at.mem].results;
          let mem = pickMem(memRows, sid);
          if (!mem) {
            mem = newMemRow(sid, pickMem(memRows, 'global'));
            await persistMemRow(db, mem, ctx);
          }

          const sessions = res[at.sessions].results ?? [];
          const curSess  = sessions.find(x => x.id === sid) ?? null;
          const genRow   = res[at.gen].results?.[0];

          // Everything the next sendMessage needs to skip its settings queries.
          cacheSet('shape:' + sid, {
            personaId:  curSess?.persona_id ?? null,
            ctxCount:   clampCtx(mem.context_count),
            fetchCount: clampFetch(mem.history_fetch_count),
            wantPins:   mem.sketchboard_active === 1,
          });

          const page = await fetchHistoryPage(db, sid, clampFetch(mem.history_fetch_count), 0);

          return jsonResponse({
            personas,
            current_persona_id: curSess?.persona_id ?? (personas[0]?.id ?? null),
            memory:             mem,
            csrf_token:         sessionDoc.csrf_token,
            session_id:         sid,
            sessions,
            username:           res[at.user].results?.[0]?.username ?? '',
            messages:           page.messages,
            has_more:           page.has_more,
            pins:               res[at.pins].results ?? [],
            sketchboard_active: mem.sketchboard_active ?? 1,
            session_missing:    !curSess,
            gen:                resolveGen(genRow),
            gen_custom:         rawGen(genRow),
          });
        }

        case 'getInitData': {
          const [personas, mem, sessions, curSess, user] = await Promise.all([
            db.all('SELECT * FROM personas ORDER BY id'),
            getMem(sid, db, ctx),
            db.all('SELECT * FROM chat_sessions ORDER BY created_at'),
            db.findOne('chat_sessions', { id: sid }),
            db.findOne('users', { id: userId }),
          ]);
          const current_persona_id = curSess?.persona_id ?? (personas[0]?.id ?? null);
          return jsonResponse({
            personas, current_persona_id, memory: mem,
            csrf_token: sessionDoc.csrf_token, session_id: sid,
            sessions, username: user?.username ?? '',
          });
        }

        case 'sendMessage': {
          const content = str(body.content, 2000089769876987698769876);
          if (!content) return errResponse('Empty or too-long message');
          const thinkingEffort = THINKING_EFFORTS.has(body.thinking_effort) ? body.thinking_effort : 'none';

          // The message is committed first; the reply is generated against it.
          let turn;
          try { turn = await reserveTurn(db, sid, content); }
          catch (e) { return errResponse('Could not save your message: ' + e.message, 500); }

          return dispatchGeneration(env, ctx, db, { kind: 'send', sid, turn, thinkingEffort });
        }

        case 'regenerate': {
          const groupId = str(body.group_id, 100);
          if (!groupId) return errResponse('Invalid group_id');
          const oldMsg = await db.get('SELECT id, session_id, group_id, timestamp FROM chat_history WHERE group_id = ? AND is_main = 1 LIMIT 1', [groupId]);
          if (!oldMsg)                   return errResponse('Not found', 404);
          if (oldMsg.session_id !== sid) return errResponse('Forbidden', 403);

          return dispatchGeneration(env, ctx, db, { kind: 'regen', sid, oldMsg });
        }

        case 'triggerSummarize': {
          const [cfg, mem] = await Promise.all([
            loadKeysAndGen(db),
            getMem(sid, db, ctx),
          ]);
          const apiKeys = cfg.apiKeys;
          const cnt    = Math.max(1, Math.min(mem.summarize_count ?? 30, 200));
          const lastTs = mem.last_summarized_timestamp ?? 0;

          let rows = await db.all(
            'SELECT * FROM chat_history WHERE session_id = ? AND is_main = 1 AND timestamp > ? ORDER BY timestamp DESC LIMIT ?',
            [sid, lastTs, cnt]
          );
          if (rows.length === 0 && lastTs > 0) {
            await db.update('memory_state', { session_id: sid }, { last_summarized_timestamp: 0 });
            rows = await db.all(
              'SELECT * FROM chat_history WHERE session_id = ? AND is_main = 1 ORDER BY timestamp DESC LIMIT ?',
              [sid, cnt]
            );
          }
          if (rows.length === 0) return jsonResponse({ success: true, summary: mem.current_summary ?? '' });

          rows.reverse();
          const lid   = rows[rows.length - 1].timestamp;
          const lines = rows.map(r => r.role.toUpperCase() + ': ' + r.content.replace(/<think>[\s\S]*?<\/think>/gi, '').trim()).join('\n');
          const old   = (mem.include_old_summary && mem.current_summary)
            ? 'Previous summary:\n' + mem.current_summary + '\n\n' : '';

          const messages = [
            { role: 'system', content: 'Summarize the chat history concisely. Keep key facts, decisions, names, and context. Use the previous generated summarize to add with your summarize to create a consistant summarize that both contain the previous chat history that are summarized and new chat history.' },
            { role: 'user',   content: old + 'Messages:\n\n' + lines },
          ];
          
          let resultText;
          try {
            // No client signal: a summary that is already running should finish and be
            // saved even if the user navigates away mid-request.
            resultText = await executeLLM(apiKeys, messages, 'summarize', 'none', false, null);
          } catch (e) {
            return errResponse(e.message, 500);
          }
          
          const cleanSummary = resultText.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

          await db.update('memory_state', { session_id: sid }, {
            current_summary: cleanSummary, last_summarized_timestamp: lid,
          });
          return jsonResponse({ success: true, summary: cleanSummary });
        }

        // What became of the newest reply in this session. A browser whose
        // stream dropped, or a brand new tab, follows the generation through
        // this until the server reports it finished.
        case 'generationStatus': {
          const row = await db.get(
            'SELECT g.bot_id, g.group_id, g.state, g.error, g.updated_at, h.content FROM active_generations g LEFT JOIN chat_history h ON h.id = g.bot_id WHERE g.session_id = ? LIMIT 1',
            [sid]);
          if (!row) return jsonResponse({ state: 'idle' });
          // A Worker stopped mid-reply never gets to write a final state.
          if (row.state === 'running' && Date.now() - (row.updated_at ?? 0) > STALL_AFTER_MS) row.state = 'stalled';
          return jsonResponse(row);
        }

        // Resolve one pasted cursor page into installable images. User-driven,
        // single page, results go straight back to the person who asked.
        /* The look, kept on the account instead of on the machine. One row,
           the same object the browser keeps locally, and a timestamp to decide
           which of two copies is the later one. */
        case 'prefs': {
          const op = str(body.op, 12);
          if (op === 'get') {
            const row = await db.get('SELECT data, updated_at FROM user_prefs WHERE user_id = ?', [userId]);
            return jsonResponse(row ? { data: row.data, updated_at: row.updated_at || 0 } : { data: null, updated_at: 0 });
          }
          if (op === 'put') {
            const data = typeof body.data === 'string' ? body.data : null;
            /* A wallpaper or a custom bubble can be pasted in as a data: URI,
               and one of those alone can run to megabytes. The row is capped
               and the client is told, rather than the write failing silently
               somewhere further down. */
            if (!data || data.length > 262144) return errResponse('Settings are too large to sync (256KB limit)');
            try { JSON.parse(data); } catch { return errResponse('Malformed settings'); }
            const now = Date.now();
            await db.run(
              'INSERT INTO user_prefs (user_id, data, updated_at) VALUES (?, ?, ?) ' +
              'ON CONFLICT(user_id) DO UPDATE SET data = excluded.data, updated_at = excluded.updated_at',
              [userId, data, now]
            );
            return jsonResponse({ ok: true, updated_at: now });
          }
          return errResponse('Unknown prefs op');
        }

        case 'resolveCursor': {
          const raw = str(body.url, 2048);
          if (!raw) return errResponse('Paste a link first');
          let u;
          try { u = safeCursorURL(raw); } catch (e) { return errResponse(e.message); }

          try {
            let urls = cursorSiteRules(u);
            if (!urls) urls = (await scrapeCursorCandidates(u)).urls;

            const out = [];
            for (const link of urls) {
              if (out.length >= 6) break;
              try {
                const img = await fetchCursorImage(link);
                if (img) out.push(img);
              } catch { /* a dead candidate is not an error */ }
            }
            if (!out.length) return errResponse('Found the page, but none of its images could be used as a cursor', 422);
            return jsonResponse({ cursors: out, source: u.toString() });
          } catch (e) {
            return errResponse(e.message, 502);
          }
        }

        case 'getChatHistory': {
          // The page size only changes from the memory modal, so scrolling back
          // through a long chat no longer re-reads memory_state every time.
          let limit = cacheGet('shape:' + sid)?.fetchCount;
          if (!limit) limit = clampFetch((await getMem(sid, db, ctx)).history_fetch_count);
          const beforeTs = parseInt(url.searchParams.get('before_timestamp') ?? '0', 10);
          return jsonResponse(await fetchHistoryPage(db, sid, limit, beforeTs));
        }

        case 'setMainVariant': {
          const id = str(body.id, 100);
          if (!id) return errResponse('Invalid id');
          const row = await db.findOne('chat_history', { id });
          if (!row)                  return errResponse('Not found', 404);
          if (row.session_id !== sid) return errResponse('Forbidden', 403);
          await db.run('UPDATE chat_history SET is_main = 0 WHERE group_id = ?', [row.group_id]);
          await db.update('chat_history', { id }, { is_main: 1 });
          return jsonResponse({ success: true });
        }

        case 'keepVersionOnly': {
          const id = str(body.id, 100);
          if (!id) return errResponse('Invalid id');
          const row = await db.findOne('chat_history', { id });
          if (!row)                  return errResponse('Not found', 404);
          if (row.session_id !== sid) return errResponse('Forbidden', 403);
          await db.run('DELETE FROM chat_history WHERE group_id = ? AND id != ?', [row.group_id, id]);
          await db.update('chat_history', { id }, { is_main: 1 });
          return jsonResponse({ success: true });
        }

        case 'editMessage': {
          const id      = str(body.id, 100);
          const content = str(body.content, 2000089769876987698769876);
          if (!id || !content) return errResponse('Invalid input');
          const row = await db.findOne('chat_history', { id });
          if (!row)                  return errResponse('Not found', 404);
          if (row.session_id !== sid) return errResponse('Forbidden', 403);
          await db.update('chat_history', { id }, { content });
          return jsonResponse({ success: true });
        }

        case 'deleteMessage': {
          const id = str(body.id, 100);
          if (!id) return errResponse('Invalid id');
          const row = await db.findOne('chat_history', { id });
          if (!row)                  return errResponse('Not found', 404);
          if (row.session_id !== sid) return errResponse('Forbidden', 403);
          await db.run('DELETE FROM chat_history WHERE group_id = ?', [row.group_id]);
          return jsonResponse({ success: true });
        }

        case 'rewindChat': {
          const id = str(body.id, 100);
          if (!id) return errResponse('Invalid id');
          const row = await db.findOne('chat_history', { id });
          if (!row)                  return errResponse('Not found', 404);
          if (row.session_id !== sid) return errResponse('Forbidden', 403);
          await db.run('DELETE FROM chat_history WHERE session_id = ? AND timestamp > ?', [sid, row.timestamp]);
          return jsonResponse({ success: true });
        }

        case 'updateSummary': {
          const summary = (typeof body.summary === 'string' ? body.summary : '').substring(0, 2000089769876987698769876);
          await db.update('memory_state', { session_id: sid }, { current_summary: summary });
          return jsonResponse({ success: true });
        }

        case 'manageKeys': {
          const op = str(body.op, 20);
          if (op === 'list') {
            const keys = await db.all('SELECT * FROM api_keys ORDER BY is_primary DESC, id');
            return jsonResponse(keys.map(k => ({ ...k, masked_key: k.api_key ? k.api_key.substring(0, 7) + '...' : '', api_key: undefined })));
          }
          if (op === 'add' || op === 'edit') {
            const provider  = str(body.provider,   50);
            const model     = str(body.model,      200);
            const keyMode   = str(body.key_mode,   20);
            const name      = str(body.name,       100) ?? '';
            const customUrl = typeof body.custom_url === 'string' ? body.custom_url.trim().substring(0, 500) : '';
            const apiKeyVal = typeof body.api_key  === 'string' ? body.api_key.trim().substring(0, 300) : '';
            const isPrimary = body.is_primary ? 1 : 0;

            if (!provider || !model || !keyMode) return errResponse('provider, model, key_mode required');
            if (!['imgxh','groq','mistral','openrouter','cloudflare','custom','gemini'].includes(provider)) return errResponse('Unknown provider');
            if (!['chat','summarize'].includes(keyMode)) return errResponse('Invalid key_mode');

            if (isPrimary) await db.run('UPDATE api_keys SET is_primary = 0 WHERE key_mode = ?', [keyMode]);

            if (op === 'add') {
              await db.insert('api_keys', {
                id: generateId(), name, provider, model, key_mode: keyMode,
                api_key: apiKeyVal, custom_url: customUrl, is_primary: isPrimary, created_at: Date.now(),
              });
            } else {
              const id = str(body.id, 100);
              if (!id) return errResponse('Missing id');
              const setFields = { name, provider, model, key_mode: keyMode, custom_url: customUrl, is_primary: isPrimary };
              if (apiKeyVal) setFields.api_key = apiKeyVal;
              await db.update('api_keys', { id }, setFields);
            }
            cacheDrop('cfg');
            return jsonResponse({ success: true });
          }
          if (op === 'delete') {
            const id = str(body.id, 100);
            if (!id) return errResponse('Invalid id');
            await db.delete('api_keys', { id });
            cacheDrop('cfg');
            return jsonResponse({ success: true });
          }
          return errResponse('Unknown op');
        }

        // Ask a provider what it can run. Proxied so the key stays server-side
        // and so CORS never enters into it.
        case 'listModels': {
          const provider = str(body.provider, 40);
          if (!provider) return errResponse('Pick a provider first');
          let apiKey = str(body.api_key, 400);
          const customUrl = str(body.custom_url, 500);
          // editing an existing endpoint: the form sends no key, so reuse the stored one
          if (!apiKey && body.id) {
            const row = await db.get('SELECT api_key FROM api_keys WHERE id = ?', [str(body.id, 100)]);
            apiKey = row?.api_key || null;
          }
          /* Google từ chối một key rỗng trong chưa đầy một phần mười giây, và
             người dùng nhận lại lỗi 502 chẳng nói lên điều gì. Hỏi trước thì
             hơn. (Provider custom có thể không cần key.) */
          if (!apiKey && provider !== 'custom') {
            return errResponse('Paste your API key first, then pick a model');
          }
          try {
            return jsonResponse(await fetchModelList(provider, apiKey, customUrl, env));
          } catch (e) {
            return errResponse(e.message, 502);
          }
        }

case 'testKey': {
          const id = str(body.id, 100);
          if (!id) return errResponse('Invalid id');
          const k = await db.findOne('api_keys', { id });
          if (!k) return errResponse('Key not found', 404);

          let target;
          try { target = chatTarget(k); }
          catch (e) { return jsonResponse({ ok: false, error: e.message.substring(0, 200) }); }

          const modelId = (k.provider === 'cloudflare' && !k.model.startsWith('@cf/')) ? `@cf/${k.model}` : k.model;

          try {
            const res = await providerCall(env, target.url, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${k.api_key ?? ''}`,
                'User-Agent':    'rsroleplay-worker/1.0',
                ...target.headers,
                
              },
              body: JSON.stringify({
                model: modelId,
                messages: [{ role: 'user', content: 'Say "ok" only.' }],
                max_tokens: 5,
                stream: false
              })
            }, 20_000);

            if (!res.ok) {
              const raw = await readBodyWithTimeout(res, ERROR_BODY_TIMEOUT_MS).catch(() => '');
              /* Ba lỗi này người dùng sửa được, nên gọi đúng tên chúng thay vì
                 ném ra mã HTTP kèm một khối JSON. */
              if (laLoiViTri(raw))    throw new Error('This provider does not serve the region this server is running in');
              if (res.status === 503) throw new Error('This model is busy right now. Wait a moment, or pick another model.');
              if (res.status === 429) throw new Error(hetLuotCaNgay(raw)
                ? 'This model has used up its free allowance for today. Pick another model, or come back tomorrow.'
                : 'This model is over its rate limit. Wait a minute, or pick another model.');
              throw new Error(`HTTP ${res.status}: ${raw}`);
            }
            return jsonResponse({ ok: true, model: k.model, provider: k.provider });
          } catch (e) {
            return jsonResponse({ ok: false, error: e.message.substring(0, 200) });
          }
        }

        case 'managePersonas': {
          const op = str(body.op, 20);
          if (op === 'list') return jsonResponse(await db.all('SELECT * FROM personas ORDER BY id'));
          if (op === 'add' || op === 'edit') {
            const name = str(body.name, 100);
            if (!name) return errResponse('Name required');
            const payload = {
              name,
              avatar:           str(body.avatar,           509887987698769876)    ?? 'AI',
              description:      str(body.description,      5000987098709870987)   ?? '',
              system_prompt:    str(body.system_prompt,    100000987098709870987) ?? '',
              user_persona:     str(body.user_persona,     5000987098709870987987)  ?? '',
              greeting_message: str(body.greeting_message, 2000987098709870987)  ?? '',
            };
            if (op === 'add') {
              await db.insert('personas', { id: generateId(), ...payload });
            } else {
              const id = str(body.id, 100);
              if (!id) return errResponse('Missing id');
              await db.update('personas', { id }, payload);
            }
            cacheDrop('personas');
            return jsonResponse({ success: true });
          }
          if (op === 'delete') {
            const id = str(body.id, 100);
            if (!id) return errResponse('Invalid id');
            await db.delete('personas', { id });
            await db.run('UPDATE chat_sessions SET persona_id = NULL WHERE persona_id = ?', [id]);
            cacheDrop('personas');
            cacheDrop('shape:');   // any session may have pointed at it
            return jsonResponse({ success: true });
          }
          return errResponse('Unknown op');
        }

        case 'setSessionPersona': {
          const sessionId = str(body.session_id, 100) ?? sid;
          const personaId = typeof body.persona_id === 'string' && body.persona_id.trim() ? body.persona_id.trim() : null;
          await db.update('chat_sessions', { id: sessionId }, { persona_id: personaId });
          cacheDrop('shape:' + sessionId);
          return jsonResponse({ success: true });
        }

        case 'updateGenSettings': {
          const g = body.gen;
          if (typeof g !== 'object' || !g) return errResponse('Invalid settings');
          const preset = GEN_PRESET_NAMES.includes(g.preset) ? g.preset : 'default';
          // The numbers are always stored, whichever preset is active, so
          // switching back to Custom restores what the user last dialled in.
          const row = { id: 'global', preset, ...rawGen(g), updated_at: Date.now() };
          const keys = Object.keys(row);
          await db.run(
            `INSERT OR REPLACE INTO gen_settings (${keys.join(', ')}) VALUES (${keys.map(() => '?').join(', ')})`,
            keys.map(k => row[k])
          );
          cacheDrop('cfg');
          return jsonResponse({ success: true, gen: resolveGen(row), gen_custom: rawGen(row) });
        }

        case 'updateMemoryConfig': {
          const m = body.memory;
          if (typeof m !== 'object' || !m) return errResponse('Invalid memory config');
          const cfg = {
            summarize_threshold:  int(m.summarize_threshold,  5, 500)  ?? 50,
            summarize_count:      int(m.summarize_count,      5, 500)  ?? 30,
            context_count:        int(m.context_count,        5, 200)  ?? 20,
            history_fetch_count:  int(m.history_fetch_count,  10, 500) ?? 50,
            include_old_summary:  m.include_old_summary ? 1 : 0,
          };
          await Promise.all([
            db.update('memory_state', { session_id: sid },      cfg),
            db.update('memory_state', { session_id: 'global' }, cfg),
          ]);
          cacheDrop('shape:');
          return jsonResponse({ success: true });
        }

        case 'updateAccount': {
          const user        = await db.findOne('users', { id: userId });
          const currentPass = str(body.current_password, 128);
          if (!currentPass) return errResponse('Current password required');
          if (!(await verifyPassword(currentPass, user.password_hash, user.salt))) return errResponse('Current password incorrect', 403);

          const newUsername = str(body.username, 64);
          if (!newUsername) return errResponse('Invalid username');
          const existing = await db.findOne('users', { username: newUsername });
          if (existing && existing.id !== userId) return errResponse('Username already taken', 409);

          const update = { username: newUsername };
          const newPass = str(body.password, 128);
          if (newPass) {
            if (newPass.length < 6) return errResponse('Password min 6 chars');
            const { hash, salt } = await pbkdf2(newPass);
            update.password_hash = hash;
            update.salt          = salt;
          }
          await db.update('users', { id: userId }, update);
// NEW: Nuke ALL sessions to enforce re-login with new credentials
          await db.delete('user_sessions', { user_id: userId });
          cacheDrop('auth:');
          
          // NEW: Clear the cookie so the current browser drops the session immediately
          return jsonResponse({ success: true }, 200, {
             'Set-Cookie': 'rsroleplay_sess=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0',
          });
        }

        case 'manageSketchboard': {
          const op = str(body.op, 20);
          if (op === 'list') {
            const [pins, mem] = await Promise.all([
              db.all('SELECT * FROM sketchboard WHERE session_id = ? ORDER BY created_at DESC', [sid]),
              getMem(sid, db, ctx),
            ]);
            return jsonResponse({ pins, global_active: mem.sketchboard_active ?? 1 });
          }
          if (op === 'add') {
            const content = str(body.content, 200075987698769976);
            if (!content) return errResponse('Empty content');
            await db.insert('sketchboard', { id: generateId(), session_id: sid, content, is_active: 1, created_at: Date.now() });
            return jsonResponse({ success: true });
          }
          if (op === 'edit') {
            const id = str(body.id, 100), content = str(body.content, 20009876987698769876);
            if (!id || !content) return errResponse('Invalid input');
            await db.run('UPDATE sketchboard SET content = ? WHERE id = ? AND session_id = ?', [content, id, sid]);
            return jsonResponse({ success: true });
          }
          if (op === 'delete') {
            const id = str(body.id, 100);
            if (!id) return errResponse('Invalid id');
            await db.run('DELETE FROM sketchboard WHERE id = ? AND session_id = ?', [id, sid]);
            return jsonResponse({ success: true });
          }
          if (op === 'togglePin') {
            const id = str(body.id, 100);
            if (!id) return errResponse('Invalid id');
            const p = await db.get('SELECT * FROM sketchboard WHERE id = ? AND session_id = ?', [id, sid]);
            if (!p) return errResponse('Not found', 404);
            await db.run('UPDATE sketchboard SET is_active = ? WHERE id = ? AND session_id = ?', [p.is_active ? 0 : 1, id, sid]);
            return jsonResponse({ success: true });
          }
          if (op === 'toggleGlobal') {
            await db.update('memory_state', { session_id: sid }, { sketchboard_active: body.active ? 1 : 0 });
            cacheDrop('shape:' + sid);
            return jsonResponse({ success: true });
          }
          return errResponse('Unknown op');
        }

        case 'manageSessions': {
          const op = str(body.op, 20);
          if (op === 'switch') {
            const sessionId = str(body.session_id, 100);
            if (!sessionId) return errResponse('Invalid session_id');
            const exist = await db.findOne('chat_sessions', { id: sessionId });
            if (!exist) return errResponse('Not found', 404);
            return jsonResponse({ success: true, session_id: sessionId });
          }
          if (op === 'new') {
            const label     = str(body.label, 100) ?? 'New Session';
            const personaId = typeof body.persona_id === 'string' && body.persona_id.trim() ? body.persona_id.trim() : null;
            const id = generateId();
            await db.insert('chat_sessions', { id, label, persona_id: personaId, created_at: Date.now() });
            const bot = personaId
              ? await db.findOne('personas', { id: personaId })
              : (await db.all('SELECT * FROM personas LIMIT 1'))[0] ?? null;
            if (bot?.greeting_message) {
              await db.insert('chat_history', {
                id: generateId(), session_id: id, group_id: 'g_' + generateId(),
                is_main: 1, role: 'bot', content: bot.greeting_message, timestamp: Date.now(),
              });
            }
            return jsonResponse({ success: true, session_id: id, label });
          }
          if (op === 'rename') {
            const sessionId = str(body.session_id, 100), label = str(body.label, 100);
            if (!sessionId || !label) return errResponse('Invalid input');
            await db.update('chat_sessions', { id: sessionId }, { label });
            return jsonResponse({ success: true });
          }
          if (op === 'delete') {
            const sessionId = str(body.session_id, 100);
            if (!sessionId) return errResponse('Invalid session_id');
            if (sessionId === 'default') return errResponse('Cannot delete default session');
            /* One batch is one transaction: a failure part-way used to leave messages
               or pins behind for a chat that no longer existed. */
            await db.d1.batch([
              db.d1.prepare('DELETE FROM chat_history WHERE session_id = ?').bind(sessionId),
              db.d1.prepare('DELETE FROM memory_state WHERE session_id = ?').bind(sessionId),
              db.d1.prepare('DELETE FROM sketchboard WHERE session_id = ?').bind(sessionId),
              db.d1.prepare('DELETE FROM chat_sessions WHERE id = ?').bind(sessionId),
            ]);
            cacheDrop('shape:' + sessionId);
            return jsonResponse({ success: true });
          }
          return errResponse('Unknown op');
        }

        case 'exportData': {
          const rows = await db.all('SELECT * FROM chat_history WHERE session_id = ? AND is_main = 1 ORDER BY timestamp', [sid]);
          const out  = rows.map(r => `{${r.role === 'user' ? 'user' : 'bot'}}\n${r.content.trim()}\n{/${r.role === 'user' ? 'user' : 'bot'}}`).join('\n\n');
          return new Response(out, {
            headers: { 'Content-Type': 'text/plain;charset=utf-8', 'Content-Disposition': `attachment; filename="chat_${Date.now()}.txt"`, ...SECURITY_HEADERS },
          });
        }

        case 'importData': {
          if (typeof body.data !== 'string') return errResponse('Invalid data');
          if (body.data.length > 500_000)    return errResponse('Import too large', 413);
          /* One D1 query per message used to hit the Free plan's 50-per-request
             limit, so a long Character.AI export stopped part-way and left half a
             chat behind. Rows now ride in as one JSON value per statement
             (INSERT ... SELECT FROM json_each), and every statement goes in one
             batch: 2-3 statements for the largest file accepted here, and a
             batch is all-or-nothing. Ids are one random prefix plus a counter,
             not a UUID per row - that is most of the CPU a big file used to cost. */
          const regex = /\{(user|bot)\}\s*([\s\S]*?)\s*\{\/(user|bot)\}/g;
          const rows = [];
          const idBase = generateId(), t0 = Date.now();
          let match;
          while ((match = regex.exec(body.data)) !== null && rows.length < 2000) {
            if (match[1] !== match[3]) continue;
            const content = match[2].trim();
            if (!content) continue;
            const n = rows.length.toString(36).padStart(4, '0');
            rows.push([idBase + '-' + n, 'g_' + idBase + '-' + n, match[1], content, t0 + rows.length]);
          }
          if (!rows.length) return jsonResponse({ success: true, imported: 0 });
          const ins = db.d1.prepare(
            'INSERT INTO chat_history (id, session_id, group_id, is_main, role, content, timestamp) ' +
            "SELECT json_extract(value, '$[0]'), ?, json_extract(value, '$[1]'), 1, " +
            "json_extract(value, '$[2]'), json_extract(value, '$[3]'), json_extract(value, '$[4]') " +
            'FROM json_each(?)');
          // well under D1's 2 MB per value even if every character is 3 bytes
          const stmts = [];
          let chunk = [], size = 0;
          for (const r of rows) {
            if (chunk.length && size + r[3].length > 400_000) {
              stmts.push(ins.bind(sid, JSON.stringify(chunk)));
              chunk = []; size = 0;
            }
            chunk.push(r); size += r[3].length + 64;
          }
          stmts.push(ins.bind(sid, JSON.stringify(chunk)));
          await db.d1.batch(stmts);
          return jsonResponse({ success: true, imported: rows.length });
        }

        case 'nukeServer': {
          const user = await db.findOne('users', { id: userId });
          const pass = str(body.password, 128);
          if (!pass) return errResponse('Password required');
          if (!(await verifyPassword(pass, user.password_hash, user.salt))) return errResponse('Wrong password', 403);

          /* One batch: one D1 call instead of eight, and all-or-nothing. The
             DELETEs used to run side by side with no transaction, so one failing
             part-way could leave the keys gone and the chats still there. The
             account is scrambled in the same transaction. */
          const { hash, salt } = await pbkdf2(crypto.randomUUID());
          await db.d1.batch([
            db.d1.prepare('DELETE FROM chat_history'),
            db.d1.prepare('DELETE FROM memory_state'),
            db.d1.prepare('DELETE FROM sketchboard'),
            db.d1.prepare('DELETE FROM personas'),
            db.d1.prepare('DELETE FROM api_keys'),
            db.d1.prepare('DELETE FROM ip_blocks'),
            db.d1.prepare('DELETE FROM chat_sessions'),
            db.d1.prepare('DELETE FROM user_sessions'),
            db.d1.prepare('UPDATE users SET username = ?, password_hash = ?, salt = ? WHERE id = ?')
              .bind(crypto.randomUUID().substring(0, 8), hash, salt, userId),
          ]);
          _cache.clear();
          return jsonResponse({ success: true }, 200, {
            'Set-Cookie': 'rsroleplay_sess=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0',
          });
        }

        default:
          return errResponse('Unknown action', 404);
      }
    } catch (e) {
      console.error('Handler error:', e);
      return errResponse(e.message || 'Internal server error', 500);
    }
  },
};


